    /// A-2/Codex R2-5: required-v1 protected reapproval opens and closes at
    /// the generic engine gate, riding the math-mode arm bodies plus the
    /// widened trust-decision command.
    #[test]
    fn required_v1_protected_gate_opens_and_closes_at_engine_gate() {
        let mut state = ProtocolState::default();
        install_minimal_required_v1_trust(&mut state);
        state.phase = Phase::ProofFormalization;
        state.trust_base.active_revision_lane_id = Some("audit-lane-1".into());
        state.pending_protected_reapproval_nodes.insert("a".into());
        state.stage = Stage::HumanGate;
        state.gate_kind = GateKind::ProtectedReapproval;
        state.cycle = 4;
        let request = issue_request_for_test(&mut state, RequestKind::HumanGate);

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::HumanGate(HumanGateResponse {
                    request_id: request.id,
                    cycle: 4,
                    status: ResponseStatus::Ok,
                    choice: HumanChoice::Approve,
                }),
            },
        )
        .expect("required-v1 protected approve rides the engine gate");
        assert_eq!(outcome.state.trust_base.active_revision_lane_id, None);
        assert!(outcome.state.pending_protected_reapproval_nodes.is_empty());
        let decision = outcome
            .commands
            .iter()
            .find_map(|command| match command {
                ProtocolCommand::CommitTrustGateDecision { kind, lane, .. } => {
                    Some((*kind, lane.clone()))
                }
                _ => None,
            })
            .expect("protected approve emits the trust-decision command");
        assert_eq!(
            decision,
            (
                crate::trust_base::EventKind::ProtectedReapprovalApproved,
                Some("audit-lane-1".to_string())
            )
        );
        assert!(outcome
            .commands
            .iter()
            .any(|command| matches!(command, ProtocolCommand::CommitCheckpoint)));
    }

