    /// Q7 (Codex 6/R3-5): the package-ready barrier completes mechanically
    /// through the `PackageFinalizationRecord` payload, re-verified inside
    /// pure `apply_event`; the four corrupted-field refusals are the R4
    /// negative set (`archive_sha256` is runtime-attested and deliberately
    /// out of scope).
    #[test]
    fn required_v1_cleanup_finalizes_from_verified_payload_and_refuses_corruption() {
        let mut state = ProtocolState::default();
        install_minimal_required_v1_trust(&mut state);
        state.phase = Phase::Cleanup;
        state.stage = Stage::Reviewer;

        finish_cleanup_or_enter_package_ready(&mut state);
        assert_eq!(state.phase, Phase::Cleanup);
        assert_eq!(state.stage, Stage::Start);
        assert!(state.trust_base.package_ready);
        state
            .validate()
            .expect("package-ready barrier must validate");

        let record = fixture_finalization_record(&state);
        // Bind the state's approval to the embedded record digest.
        state.trust_base.current_human_approval_event_hash = Some(record.approval_record_sha256);

        // finalize_refused_on_missing_embedded_approval: a record whose
        // embedded approval fails digest verification refuses.
        let mut missing = record.clone();
        missing.approval_record.record_sha256 = crate::trust_base::Sha256Digest::ZERO;
        let error = apply_event(
            state.clone(),
            ProtocolEvent::FinalizeAuthorizedPackage { record: missing },
        )
        .expect_err("corrupted embedded approval must refuse");
        assert!(matches!(error, TransitionError::IllegalResponse(message)
            if message.contains("invalid approval record")));

        // finalize_refused_on_mismatched_approval_digest.
        let mut mismatched = record.clone();
        mismatched.approval_record_sha256 = crate::trust_base::raw_sha256(b"other");
        let error = apply_event(
            state.clone(),
            ProtocolEvent::FinalizeAuthorizedPackage { record: mismatched },
        )
        .expect_err("mismatched approval digest must refuse");
        assert!(matches!(error, TransitionError::IllegalResponse(message)
            if message.contains("approval digest")));

        // finalize_refused_on_stale_presentation_hash.
        let mut stale = record.clone();
        stale.presentation_sha256 = crate::trust_base::raw_sha256(b"stale presentation");
        let error = apply_event(
            state.clone(),
            ProtocolEvent::FinalizeAuthorizedPackage { record: stale },
        )
        .expect_err("stale presentation hash must refuse");
        assert!(matches!(error, TransitionError::IllegalResponse(message)
            if message.contains("presentation hash")));

        // finalize_refused_on_corrupted_finalization_payload_field: seed
        // roots and cycle corrupted in turn.
        let mut roots = record.clone();
        roots.seed_roots.authored_semantic_root = crate::trust_base::raw_sha256(b"drift");
        let error = apply_event(
            state.clone(),
            ProtocolEvent::FinalizeAuthorizedPackage { record: roots },
        )
        .expect_err("corrupted seed roots must refuse");
        assert!(matches!(error, TransitionError::IllegalResponse(message)
            if message.contains("seed roots")));
        let mut cycle = record.clone();
        cycle.cycle = record.cycle + 1;
        let error = apply_event(
            state.clone(),
            ProtocolEvent::FinalizeAuthorizedPackage { record: cycle },
        )
        .expect_err("corrupted cycle must refuse");
        assert!(matches!(error, TransitionError::IllegalResponse(message)
            if message.contains("cycle")));

        // The exact payload finalizes mechanically and stores the IDENTICAL
        // record as state (replay-reproducible finalization).
        let outcome = apply_event(
            state.clone(),
            ProtocolEvent::FinalizeAuthorizedPackage {
                record: record.clone(),
            },
        )
        .expect("verified finalization payload must complete mechanically");
        assert_eq!(outcome.state.phase, Phase::Complete);
        assert_eq!(outcome.state.stage, Stage::Complete);
        assert!(!outcome.state.trust_base.package_ready);
        assert_eq!(
            outcome.state.trust_base.package_finalization,
            Some(record.clone())
        );
        assert!(matches!(
            outcome.commands.as_slice(),
            [ProtocolCommand::CommitCheckpoint]
        ));

        // replay_reproduces_package_finalization_from_event_payload (Codex
        // R3-5): replaying the same event over the same pre-state
        // reproduces the identical stored finalization.
        let replayed = apply_event(
            state,
            ProtocolEvent::FinalizeAuthorizedPackage {
                record: record.clone(),
            },
        )
        .expect("replay reproduces finalization");
        assert_eq!(replayed.state.trust_base.package_finalization, Some(record));
        assert_eq!(replayed.state, outcome.state);
    }

    /// Q7: the enum has no `PackageAuthorized` event; finalization is the
    /// payload-carrying `FinalizeAuthorizedPackage` terminal (exhaustive
    /// match — compiling it IS the assertion).
    #[test]
    fn no_package_authorized_event_exists() {
        let record = fixture_finalization_record(&{
            let mut state = ProtocolState::default();
            install_minimal_required_v1_trust(&mut state);
            state
        });
        let event = ProtocolEvent::FinalizeAuthorizedPackage { record };
        match &event {
            ProtocolEvent::StartCycle
            | ProtocolEvent::FinalizeAuthorizedPackage { .. }
            | ProtocolEvent::WrapperResponse { .. }
            | ProtocolEvent::SidecarClosure { .. }
            | ProtocolEvent::SidecarAttemptOutcomes { .. }
            | ProtocolEvent::SidecarQueueAutoAdd { .. }
            | ProtocolEvent::StatementBound { .. }
            | ProtocolEvent::ConditionalActivation { .. } => {}
        }
        let serialized = serde_json::to_string(&event).unwrap();
        assert!(serialized.contains("\"finalize_authorized_package\""));
        assert!(!serialized.contains("package_authorized\""));
    }

