    #[test]
    fn corr_verdict_in_cleanup_is_accepted_and_routed_instead_of_hard_erroring() {
        // `route_after_progress` dispatches Corr from the end of every
        // accepted cleanup burst with no phase gate, and a fresh helper
        // is a dispatch-eligible corr-Unknown leaf. Before the Cleanup
        // arm existed, `apply_corr_response` answered that verdict with
        // `InvalidPhase` — the first extraction would have hard-errored
        // the supervisor.
        let mut state = cleanup_state_with_helper();
        state.stage = Stage::VerifyCorr;
        state.cycle = 8;
        state
            .live
            .corr_current_fingerprints
            .insert("Helper".into(), "chelper-drifted".into());
        assert!(!state.formalization_complete());
        assert!(state.formalization_valid());
        let request = issue_request_for_test(&mut state, RequestKind::Corr);

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Corr(CorrResponse {
                    request_id: request.id,
                    cycle: 8,
                    status: ResponseStatus::Ok,
                    node_lane_updates: pass_corr_node_lanes(&request.verify_lanes, "Helper"),
                    target_lane_updates: empty_corr_target_lanes(&request.verify_lanes),
                    reviewer_evidence: BTreeMap::new(),
                    rust_witness_artifact_correspondence: None,
                    conditional_theorem_correspondence: None,
                }),
            },
        )
        .expect("a corr verdict in Cleanup must be accepted, not InvalidPhase");

        assert_eq!(outcome.state.phase, Phase::Cleanup);
        assert!(
            outcome.state.current_corr_pass(&NodeId::from("Helper")),
            "the Pass verdict must be applied, clearing the blocker"
        );
        assert!(
            outcome.state.formalization_complete(),
            "with the blocker cleared there is no outstanding work left"
        );
        assert!(
            outcome
                .commands
                .iter()
                .any(|command| matches!(command, ProtocolCommand::IssueRequest { .. })),
            "the accept must route onwards, not stall"
        );
    }

    #[test]
    fn cleanup_auto_done_waits_for_the_corr_blocker_it_can_now_carry() {
        // Sub-case B's auto-Done used to fire on "no Pending tasks
        // remain" alone, resting on the old per-burst predicate having
        // made every Cleanup boundary work-free. Under
        // `formalization_valid` that no longer holds, so an ungated
        // auto-Done would carry a live blocker into Phase::Complete.
        let mut blocked = cleanup_state_with_helper();
        blocked.stage = Stage::Reviewer;
        blocked
            .live
            .corr_current_fingerprints
            .insert("Helper".into(), "chelper-drifted".into());
        let outcome = apply_cleanup_review_response(&mut blocked, cleanup_continue_response())
            .expect("dismiss-only Continue is legal");
        assert_eq!(blocked.phase, Phase::Cleanup, "must not auto-Done");
        assert!(
            outcome
                .iter()
                .any(|command| matches!(command, ProtocolCommand::IssueRequest { .. })),
            "the re-issue path must dispatch, and via route_after_progress"
        );

        // Same shape with the blocker cleared: auto-Done fires as before.
        let mut clear = cleanup_state_with_helper();
        clear.stage = Stage::Reviewer;
        assert!(clear.formalization_complete());
        apply_cleanup_review_response(&mut clear, cleanup_continue_response())
            .expect("dismiss-only Continue is legal");
        assert_ne!(
            clear.phase,
            Phase::Cleanup,
            "with no work outstanding and no tasks pending, auto-Done still fires"
        );
    }

    fn cleanup_continue_response() -> ReviewResponse {
        ReviewResponse {
            decision: ReviewDecisionKind::Continue,
            next_mode: TaskMode::Cleanup,
            allow_new_obligations: true,
            must_close_active: false,
            ..ReviewResponse::default()
        }
    }

    #[test]
    fn cleanup_repair_dispatch_sets_a_worker_burst_scoped_to_the_repaired_node() {
        let mut state = cleanup_state_with_helper();
        state.stage = Stage::Reviewer;
        state
            .live
            .corr_current_fingerprints
            .insert("Helper".into(), "chelper-drifted".into());
        let response = ReviewResponse {
            cleanup_repair_node: Some(NodeId::from("Helper")),
            ..cleanup_continue_response()
        };
        apply_cleanup_review_response(&mut state, response).expect("repair dispatch is legal");

        assert_eq!(state.stage, Stage::Start, "a repair is a worker dispatch");
        assert_eq!(state.cleanup_repair_node, Some(NodeId::from("Helper")));
        assert_eq!(state.active_node, Some(NodeId::from("Helper")));
        assert!(state.cleanup_active_task.is_none());
        assert!(state.cleanup_active_batch.is_empty());
        assert!(state.pending_task.is_some());
        assert_eq!(
            state.current_worker_authorized_nodes(),
            BTreeSet::from([NodeId::from("Helper")])
        );
        assert!(
            matches!(
                state.current_worker_validation_execution_plan().as_slice(),
                [WorkerValidationExecutionPlanStep::FinalCleanupCorrRepair { node }]
                    if node.as_deref() == Some("Helper")
            ),
            "the marker must select the repair envelope: {:?}",
            state.current_worker_validation_execution_plan()
        );
    }

    #[test]
    fn failed_repair_bursts_count_towards_the_non_convergence_latch() {
        // A repair has no task to mark Failed, so without a branch of its
        // own `mark_cleanup_task_failed` would early-return and a node
        // whose prose never lands would spin the reviewer forever with
        // the latch never firing.
        let mut state = cleanup_state_with_helper();
        for _ in 0..CLEANUP_CONSECUTIVE_INVALID_THRESHOLD {
            state.cleanup_repair_node = Some(NodeId::from("Helper"));
            mark_cleanup_task_failed(&mut state, "repair burst invalid".to_string());
            assert!(state.cleanup_repair_node.is_none(), "marker released");
        }
        assert_eq!(
            state.cleanup_consecutive_invalid_workers,
            CLEANUP_CONSECUTIVE_INVALID_THRESHOLD
        );
        assert!(state.cleanup_force_done);
    }

    fn empty_corr_node_lanes(lanes: &BTreeSet<LaneId>) -> CorrNodeLaneUpdates {
        lanes
            .iter()
            .map(|lane| (lane.clone(), BTreeMap::new()))
            .collect()
    }

    fn pass_corr_node_lanes(lanes: &BTreeSet<LaneId>, node: &str) -> CorrNodeLaneUpdates {
        lanes
            .iter()
            .map(|lane| {
                (
                    lane.clone(),
                    BTreeMap::from([(NodeId::from(node), Update::Set(CorrStatus::Pass))]),
                )
            })
            .collect()
    }

    fn empty_corr_target_lanes(lanes: &BTreeSet<LaneId>) -> CorrTargetLaneUpdates {
        lanes
            .iter()
            .map(|lane| (lane.clone(), BTreeMap::new()))
            .collect()
    }

    fn unanimous_sound_lanes(
        lanes: &BTreeSet<LaneId>,
        node: &str,
        status: SoundStatus,
    ) -> SoundLaneUpdates {
        lanes
            .iter()
            .map(|lane| {
                (
                    lane.clone(),
                    BTreeMap::from([(NodeId::from(node), Update::Set(status))]),
                )
            })
            .collect()
    }

    fn disagree_sound_lanes(lanes: &BTreeSet<LaneId>, node: &str) -> SoundLaneUpdates {
        let mut out = BTreeMap::new();
        for (idx, lane) in lanes.iter().enumerate() {
            let status = if idx == 0 {
                SoundStatus::Pass
            } else {
                SoundStatus::Fail
            };
            out.insert(
                lane.clone(),
                BTreeMap::from([(NodeId::from(node), Update::Set(status))]),
            );
        }
        out
    }

    fn disagree_corr_node_lanes(lanes: &BTreeSet<LaneId>, node: &str) -> CorrNodeLaneUpdates {
        let mut out = BTreeMap::new();
        for (idx, lane) in lanes.iter().enumerate() {
            let status = if idx == 0 {
                CorrStatus::Pass
            } else {
                CorrStatus::Fail
            };
            out.insert(
                lane.clone(),
                BTreeMap::from([(NodeId::from(node), Update::Set(status))]),
            );
        }
        out
    }

