    #[test]
    fn standing_baseline_orphan_does_not_reject_unrelated_valid_worker_response() {
        // dec2flt cycles 279-282: the polarity flip stranded the demoted
        // side's support helpers (present, no importer, outside every
        // coverage root); the absolute orphan gate then rejected EVERY
        // Valid worker response — including an Assumptions-only edit that
        // could not have touched them. The gate rejects only orphans the
        // burst itself creates.
        let mut state = base_state();
        state.stage = Stage::Worker;
        state.cycle = 4;
        state.deps.insert("a".into(), set(&["b"]));
        state.committed_deps = state.deps.clone();
        state.live.present_nodes.insert("stranded_helper".into());
        state.normalize_all_structural_state();
        state.ensure_node_metadata();
        assert!(
            state.orphan_cleanup_needed(),
            "precondition: the standing orphan is real pre-burst"
        );
        let request = issue_request_for_test(&mut state, RequestKind::Worker);
        let mut changed = state.live.clone();
        changed
            .corr_current_fingerprints
            .insert("b".into(), "cb2".into());
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(WorkerResponse {
                    request_id: request.id,
                    cycle: 4,
                    status: ResponseStatus::Ok,
                    outcome: WorkerOutcome::Valid,
                    snapshot: changed,
                    difficulty_updates: BTreeMap::new(),
                    ..WorkerResponse::default()
                }),
            },
        )
        .unwrap();
        // Accepted (routes to a verifier stage — VerifyPaper here because the
        // extra present node enlarges the substantiveness frontier), never
        // bounced back to Worker with a rejection.
        assert_eq!(
            outcome.state.stage,
            Stage::VerifyPaper,
            "a pre-existing orphan must not reject an unrelated Valid response"
        );
        assert!(outcome
            .state
            .deterministic_worker_rejection_reasons
            .is_empty());
    }

    #[test]
    fn newly_created_orphan_rejects_valid_worker_response_naming_the_node() {
        let mut state = base_state();
        state.stage = Stage::Worker;
        state.cycle = 4;
        state.deps.insert("a".into(), set(&["b"]));
        state.committed_deps = state.deps.clone();
        assert!(!state.orphan_cleanup_needed(), "precondition: orphan-free");
        let request = issue_request_for_test(&mut state, RequestKind::Worker);
        let mut changed = state.live.clone();
        changed
            .corr_current_fingerprints
            .insert("a".into(), "ca2".into());
        // The burst drops a's import of b, stranding b.
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(WorkerResponse {
                    request_id: request.id,
                    cycle: 4,
                    status: ResponseStatus::Ok,
                    outcome: WorkerOutcome::Valid,
                    snapshot: changed,
                    dep_updates: BTreeMap::from([(
                        NodeId::from("a"),
                        Update::Set(BTreeSet::new()),
                    )]),
                    difficulty_updates: BTreeMap::new(),
                    ..WorkerResponse::default()
                }),
            },
        )
        .unwrap();
        assert_eq!(
            outcome.state.stage,
            Stage::Worker,
            "a newly-created orphan must reject the response into a retry"
        );
        assert!(
            outcome
                .state
                .deterministic_worker_rejection_reasons
                .iter()
                .any(|r| r.contains("NEW live orphan nodes") && r.contains("b")),
            "rejection must name the new orphan: {:?}",
            outcome.state.deterministic_worker_rejection_reasons
        );
    }

    /// Shared driver for the uncovered-target orphan-window engine tests:
    /// starts from `base_state` plus an extra configured-but-uncovered
    /// target `t2` (window OPEN), and replays the exact burst of
    /// `newly_created_orphan_rejects_valid_worker_response_naming_the_node`
    /// (dropping `a`'s import of `b`, stranding `b`).
    fn window_open_orphan_burst_outcome(phase: Phase) -> TransitionOutcome {
        let mut state = base_state();
        state.phase = phase;
        state.stage = Stage::Worker;
        state.cycle = 4;
        state.configured_targets.insert("t2".into());
        state.deps.insert("a".into(), set(&["b"]));
        state.committed_deps = state.deps.clone();
        state.normalize_all_structural_state();
        assert!(
            state.orphan_construction_window_open(&state.live),
            "precondition: t2 is configured but uncovered, window open"
        );
        assert!(!state.orphan_cleanup_needed(), "precondition: orphan-free");
        let request = issue_request_for_test(&mut state, RequestKind::Worker);
        let mut changed = state.live.clone();
        changed
            .corr_current_fingerprints
            .insert("a".into(), "ca2".into());
        apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(WorkerResponse {
                    request_id: request.id,
                    cycle: 4,
                    status: ResponseStatus::Ok,
                    outcome: WorkerOutcome::Valid,
                    snapshot: changed,
                    dep_updates: BTreeMap::from([(
                        NodeId::from("a"),
                        Update::Set(BTreeSet::new()),
                    )]),
                    difficulty_updates: BTreeMap::new(),
                    ..WorkerResponse::default()
                }),
            },
        )
        .unwrap()
    }

    #[test]
    fn uncovered_target_window_accepts_new_orphan_in_theorem_stating() {
        // Window OPEN (t2 uncovered): the very burst the closed-window
        // twin above rejects is accepted — layered, support-first
        // construction — and routing proceeds normally (no bounce back
        // to Worker, no orphan-cleanup task parked).
        let outcome = window_open_orphan_burst_outcome(Phase::TheoremStating);
        assert_ne!(
            outcome.state.stage,
            Stage::Worker,
            "window-open new orphan must not bounce the response into a retry"
        );
        assert!(outcome
            .state
            .deterministic_worker_rejection_reasons
            .is_empty());
        assert!(
            !outcome.state.orphan_cleanup_active(),
            "no orphan-cleanup task may be parked while the window is open"
        );
        assert!(
            outcome.state.orphan_cleanup_needed(),
            "raw orphan detection must still see the tolerated orphan"
        );
    }

