    #[test]
    fn cleanup_valid_can_remove_orphan_node() {
        let mut state = base_state();
        state.phase = Phase::Cleanup;
        state.stage = Stage::Worker;
        state.cycle = 7;
        // Cleanup invariant: every accepted state must be Done-valid.
        // Close the proof node so the resulting burst keeps the invariant.
        state.live.open_nodes.remove("a");
        // Patch C plan §7.6: `formalization_complete` now requires a
        // `LocalClosureRecord` for every sorry-free proof_node.
        install_placeholder_local_closure_record(&mut state, "a");
        state.committed = state.live.clone();
        let request = issue_request_for_test(&mut state, RequestKind::Worker);
        let mut changed = state.live.clone();
        changed.present_nodes.remove("b");
        changed.open_nodes.remove("b");
        changed.corr_current_fingerprints.remove("b");

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(WorkerResponse {
                    request_id: request.id,
                    cycle: 7,
                    status: ResponseStatus::Ok,
                    outcome: WorkerOutcome::Valid,
                    snapshot: changed,
                    difficulty_updates: BTreeMap::new(),
                    ..WorkerResponse::default()
                }),
            },
        )
        .unwrap();

        assert_eq!(outcome.state.stage, Stage::Reviewer);
        assert_eq!(outcome.state.live.present_nodes, set(&["a"]));
        assert!(outcome.state.live.open_nodes.is_empty());
        assert!(!outcome
            .state
            .live
            .corr_current_fingerprints
            .contains_key("b"));
        assert!(matches!(
            &outcome.commands[0],
            ProtocolCommand::IssueRequest { request }
                if request.kind == RequestKind::Review
        ));
    }

    #[test]
    fn real_normalizer_and_cleanup_engine_accept_zero_new_orphans_over_dirty_baseline() {
        // Production regression for burst 5630's failure class. Build the
        // response through the real disk normalizer; do not hand-assemble a
        // WorkerResponse shape the normalizer cannot emit.
        let directory = tempfile::tempdir().expect("temporary tablet repo");
        let tablet = directory.path().join("Tablet");
        std::fs::create_dir_all(&tablet).expect("create Tablet");
        std::fs::write(
            tablet.join("a.lean"),
            "theorem a : True := by\n-- BODY\n  trivial\n",
        )
        .expect("write root Lean node");
        std::fs::write(
            tablet.join("a.tex"),
            "\\begin{theorem}Root.\\end{theorem}\n\\begin{proof}Trivial.\\end{proof}\n",
        )
        .expect("write root TeX node");
        std::fs::write(
            tablet.join("b.lean"),
            "def b : True := True.intro\n-- BODY\n",
        )
        .expect("write orphan Lean node");
        std::fs::write(
            tablet.join("b.tex"),
            "\\begin{definition}An unused definition.\\end{definition}\n",
        )
        .expect("write orphan TeX node");

        let mut state = base_state();
        state.phase = Phase::Cleanup;
        state.stage = Stage::Worker;
        state.cycle = 7;
        state.live.open_nodes.clear();
        state.node_kinds.insert("a".into(), NodeKind::Proof);
        state.node_kinds.insert("b".into(), NodeKind::Definition);
        install_placeholder_local_closure_record(&mut state, "a");
        // Certificate v2 widened closure ownership from `proof_nodes` to
        // every present node satisfying `local_closure_owner_eligible` —
        // Proof, Definition and Preamble alike. The orphan "b" is a present
        // Definition, so it is an eligible owner and must carry a record:
        // `runtime::require_local_closure_records` refuses to begin work at
        // any authoritative apply site while an eligible owner has none, so
        // a recordless "b" is not a state the system can be in. The
        // baseline is dirty in the ORPHAN dimension only — "b" is present,
        // closed, certified and unreachable from any target — which is
        // exactly the condition this test holds the cleanup accept path to.
        // Leaving the baseline invalid instead would silently disarm the
        // test: `evaluate_cleanup_transition_preflight` only charges a
        // formalization regression when the BASELINE was valid.
        install_placeholder_local_closure_record(&mut state, "b");
        state.committed = state.live.clone();
        state.committed_proof_nodes = state.proof_nodes.clone();
        state.committed_node_kinds = state.node_kinds.clone();
        state.committed_deps = state.deps.clone();
        state.committed_target_claims = state.target_claims.clone();
        assert!(
            state.formalization_valid(),
            "baseline formalization is valid"
        );
        assert_eq!(state.orphan_nodes(&state.live), set(&["b"]));

        let request = issue_request_for_test(&mut state, RequestKind::Worker);
        assert_eq!(request.current_orphan_nodes, set(&["b"]));
        assert!(request.cleanup_baseline_formalization_valid);
        assert_eq!(
            request.worker_contract["request_summary"]["cleanup_transition_obligation"]
                ["baseline_live_orphans"],
            serde_json::json!(["b"])
        );
        assert_eq!(
            request.worker_contract["request_summary"]["cleanup_transition_obligation"]
                ["required_postcondition"],
            "post live orphan nodes must be a subset of baseline live orphan nodes"
        );

        let validation_step = WorkerValidationExecutionPlanStep::FinalCleanupPreserving {
            task_kind: None,
            target_node: None,
            task_obligations: BTreeMap::new(),
            authorized_nodes: BTreeSet::new(),
            protected_statement_node_set: BTreeSet::new(),
        };
        let normalized = crate::worker_normalization::accept_worker_response(
            &crate::worker_normalization::WorkerAcceptanceInput {
                request_id: request.id,
                cycle: request.cycle,
                payload_outcome: WorkerOutcome::Valid,
                before_snapshot: crate::worker_normalization::snapshot_tablet_dir(directory.path()),
                validation_execution_plan: vec![validation_step],
                validation_step_results: vec![
                    crate::worker_normalization::WorkerValidationStepResult {
                        kind: "final_cleanup_preserving".into(),
                        ok: true,
                        ..Default::default()
                    },
                ],
                cleanup_transition_preflight_required: true,
                cleanup_baseline_formalization_valid: true,
                cleanup_enforce_formalization_validity: true,
                normalization: crate::worker_normalization::WorkerNormalizationInput {
                    repo_path: directory.path().to_path_buf(),
                    configured_targets: state.configured_targets.clone(),
                    current_present_nodes: state.live.present_nodes.clone(),
                    current_proof_nodes: state.proof_nodes.clone(),
                    current_node_kinds: state.node_kinds.clone(),
                    current_deps: state.deps.clone(),
                    current_target_claims: state.target_claims.clone(),
                    approved_paper_fingerprints: state.paper_approved_fingerprints.clone(),
                    target_fingerprints: state.live.corr_current_fingerprints.clone(),
                    sound_current_fingerprints: state.live.sound_current_fingerprints.clone(),
                    ..Default::default()
                },
                ..Default::default()
            },
        )
        .expect("real worker normalizer executes");
        assert!(normalized.ok, "normalizer errors: {:?}", normalized.errors);
        let checker_preflight = normalized
            .response
            .cleanup_transition_preflight
            .as_ref()
            .expect("cleanup normalizer emits transition preflight");
        assert!(checker_preflight.accepted());
        assert_eq!(checker_preflight.baseline_live_orphans, set(&["b"]));
        assert!(checker_preflight.newly_created_live_orphans.is_empty());

        // The runtime hydrate phase restores the fingerprint fields after
        // normalization. Mirror that deterministic carrier population here;
        // it does not affect graph/orphan transition inputs.
        let mut response = normalized.response;
        response.snapshot.corr_current_fingerprints = state.live.corr_current_fingerprints.clone();
        response.snapshot.target_fingerprints = state.live.target_fingerprints.clone();
        response.snapshot.paper_current_fingerprints =
            state.live.paper_current_fingerprints.clone();
        response.snapshot.sound_current_fingerprints =
            state.live.sound_current_fingerprints.clone();
        response.snapshot.sound_current_fingerprint_parts =
            state.live.sound_current_fingerprint_parts.clone();
        response.snapshot.deviation_current_fingerprints =
            state.live.deviation_current_fingerprints.clone();
        response.snapshot.sketch_proof_nodes = state.live.sketch_proof_nodes.clone();
        response.snapshot.placeholder_definition_nodes =
            state.live.placeholder_definition_nodes.clone();
        response.snapshot.substantiveness_current_fingerprints =
            state.live.substantiveness_current_fingerprints.clone();
        response.snapshot.protected_closure_nodes_per_target =
            state.live.protected_closure_nodes_per_target.clone();
        response.snapshot.challenge_coverage = state.live.challenge_coverage.clone();
        assert_eq!(
            response.snapshot, state.live,
            "normalization plus runtime hydration reproduces the no-op snapshot"
        );
        response.acceptance_check_passed = true;

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(response),
            },
        )
        .expect("engine applies checker-accepted response");
        assert!(
            outcome
                .state
                .deterministic_worker_rejection_reasons
                .is_empty(),
            "engine rejection reasons: {:?}",
            outcome.state.deterministic_worker_rejection_reasons
        );
        assert!(!outcome
            .commands
            .iter()
            .any(|command| matches!(command, ProtocolCommand::RestoreWorktreeToActiveWorkerBase)));
        assert_eq!(outcome.state.orphan_nodes(&outcome.state.live), set(&["b"]));
    }

    #[test]
    fn cleanup_valid_target_deletion_relegalizes_active_node() {
        let mut state = base_state();
        state.phase = Phase::Cleanup;
        state.stage = Stage::Worker;
        state.cycle = 41;
        state.active_node = Some(NodeId::from("b"));
        state.cleanup_audit_tasks = vec![CleanupAuditTask {
            target_node: NodeId::from("b"),
            rationale: "drop redundant wrapper".into(),
            confidence: CleanupTaskConfidence::High,
            kind: CleanupTaskKind::Substitution {
                replacement: CleanupReplacement::Mathlib {
                    citation: "Nat.choose_symm".into(),
                },
            },
            status: CleanupTaskStatus::Pending,
            audit_origin_round: 1,
            swept_parents: BTreeSet::new(),
            region_block_lines: None,
        }];
        state.cleanup_active_task = Some(0);
        state.live.open_nodes.remove("a");
        install_placeholder_local_closure_record(&mut state, "a");
        state.committed = state.live.clone();
        let request = issue_request_for_test(&mut state, RequestKind::Worker);
        let mut changed = state.live.clone();
        changed.present_nodes.remove("b");
        changed.open_nodes.remove("b");
        changed.corr_current_fingerprints.remove("b");
        let response = WorkerResponse {
            request_id: request.id,
            cycle: 41,
            status: ResponseStatus::Ok,
            outcome: WorkerOutcome::Valid,
            snapshot: changed,
            deleted_nodes: set(&["b"]),
            ..WorkerResponse::default()
        };

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(response),
            },
        )
        .expect("valid cleanup target deletion should not leave illegal active node");

        assert!(outcome.state.active_node.is_none());
        assert!(matches!(
            outcome.state.cleanup_audit_tasks[0].status,
            CleanupTaskStatus::Completed
        ));
        assert!(outcome.state.cleanup_active_task.is_none());
        assert!(!outcome.state.live.present_nodes.contains("b"));
        assert_eq!(outcome.state.stage, Stage::Reviewer);
    }

