    /// PV Phase 7 — Slice 1. An `ExtractionModel` role on a node suppresses
    /// its Correspondence (and Substantiveness) lane DESPITE the node being
    /// a Proof node. With the corr fingerprint drifted to Unknown, the
    /// no-role state drains the corr frontier (routes to `Corr`); seeding
    /// `node_role["a"] = ExtractionModel` makes `current_corr_state("a")`
    /// report Pass, so "a" carries no corr blocker, leaves
    /// `corr_verify_nodes()`, and the SAME engine router (`apply_proof_corr_
    /// accept`, byte-unchanged) falls through to Review — never Corr, never
    /// Sound. Mirrors `proof_corr_accept_does_not_route_sound_for_non_proof_
    /// active_node`, swapping the kind gate for the role suppression.
    fn extraction_model_corr_drift_base() -> ProtocolState {
        let mut state = base_state();
        state.phase = Phase::ProofFormalization;
        state.stage = Stage::VerifyCorr;
        state.cycle = 8;
        state.active_node = Some("a".into());
        // Drift "a"'s corr to Unknown so the no-role state has live corr work.
        state
            .live
            .corr_current_fingerprints
            .insert("a".into(), "ca-drifted".into());
        state
    }

    #[test]
    fn extraction_model_role_routes_corr_drift_node_to_corr_without_role() {
        // Contrapositive guard: with NO role, the drifted corr node "a"
        // lands on the corr frontier AND carries a non-adjudicable NodeCorr
        // blocker — the exact pair the `apply_proof_corr_accept` drain tests
        // (`!corr_verify_nodes().is_empty()` + the NodeCorr blocker) to route
        // to Corr. This proves the role (not the fixture) is what suppresses
        // below: the WITH-role test sees neither and falls through to Review.
        let state = extraction_model_corr_drift_base();
        assert!(state.node_role.is_empty());
        assert!(state.corr_verify_nodes().contains("a"));
        assert!(state.has_non_adjudicable_unknown_blocker(BlockerKind::NodeCorr));
    }

    #[test]
    fn extraction_model_role_suppresses_corr_and_sound_despite_proof_kind() {
        let mut state = extraction_model_corr_drift_base();
        // "a" is a Proof node (in proof_nodes); seed the ExtractionModel role.
        assert!(state.proof_nodes.contains("a"));
        state.node_role.insert("a".into(), PvRole::ExtractionModel);
        // The role forces corr Pass and drops "a" off the corr frontier.
        assert_eq!(
            state.current_corr_state(&"a".into()),
            CurrentCheckState::Pass
        );
        assert!(!state.corr_verify_nodes().contains("a"));
        // No corr blocker either (so the router's drain guard is not armed).
        assert!(!state.has_non_adjudicable_unknown_blocker(BlockerKind::NodeCorr));
        // Sound is Pass in base_state (no sound work) ⇒ off the sound frontier.
        assert!(state.sound_verify_nodes().is_empty());

        let request = issue_request_for_test(&mut state, RequestKind::Corr);
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Corr(CorrResponse {
                    request_id: request.id,
                    cycle: 8,
                    status: ResponseStatus::Ok,
                    node_lane_updates: empty_corr_node_lanes(&request.verify_lanes),
                    target_lane_updates: empty_corr_target_lanes(&request.verify_lanes),
                    reviewer_evidence: BTreeMap::new(),
                    rust_witness_artifact_correspondence: None,
                    conditional_theorem_correspondence: None,
                }),
            },
        )
        .unwrap();
        // Routes to Review — never Corr, never Sound — DESPITE the Proof kind.
        assert_eq!(outcome.commands.len(), 1);
        match &outcome.commands[0] {
            ProtocolCommand::IssueRequest { request } => {
                assert_eq!(request.kind, RequestKind::Review);
                assert_ne!(request.kind, RequestKind::Corr);
                assert_ne!(request.kind, RequestKind::Sound);
            }
            other => panic!("expected review request, got {other:?}"),
        }
    }

    #[test]
    fn human_approve_advance_enters_proof_formalization_start() {
        let mut state = base_state();
        state.stage = Stage::HumanGate;
        state.cycle = 10;
        state.configured_targets = set(&["t"]);
        state.gate_kind = GateKind::Advance;
        state
            .live
            .target_fingerprints
            .insert("a".into(), "ct-live-node".into());
        state
            .live
            .paper_current_fingerprints
            .insert("t".into(), "a=ct-live-node".into());
        let request = issue_request_for_test(&mut state, RequestKind::HumanGate);

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::HumanGate(HumanGateResponse {
                    request_id: request.id,
                    cycle: 10,
                    status: ResponseStatus::Ok,
                    choice: HumanChoice::Approve,
                }),
            },
        )
        .unwrap();
        assert_eq!(outcome.state.phase, Phase::ProofFormalization);
        assert_eq!(outcome.state.stage, Stage::Start);
        assert_eq!(
            outcome.state.approved_targets.configured_targets,
            set(&["t"])
        );
        assert_eq!(
            outcome
                .state
                .paper_approved_fingerprints
                .get("t")
                .map(String::as_str),
            Some("a=ct-live-node")
        );
        // Phase entry leaves both `active_node` and `active_coarse_node`
        // as None: the post-advance routing Review (issued by the next
        // `start_cycle` because `post_advance_routing_pending=true`) is
        // responsible for choosing `next_active` and `next_active_coarse`
        // with full latitude over all open coarse-DAG nodes. Pre-seeding
        // the anchor here would narrow `kernel_hinted_next_active_nodes`
        // to the anchor's cone AND empty out
        // `kernel_hinted_next_active_coarse_nodes` (anchor locked), defeating
        // the routing Review's purpose. `30b_coarse_anchor.md` documents
        // the `active_coarse_node = None` state as legitimate: the kernel
        // surfaces every open coarse-DAG node and the reviewer's Continue
        // must set `next_active_coarse`.
        assert_eq!(
            outcome.state.active_node, None,
            "phase entry must leave active_node = None for the routing Review to choose"
        );
        assert_eq!(
            outcome.state.active_coarse_node, None,
            "phase entry must leave active_coarse_node = None for the routing Review to choose"
        );
        // Audit Finding 5: human-approved phase advance emits
        // CommitCheckpoint so the git/audit boundary records the phase
        // transition (state.phase is the only persistent record of which
        // phase we're in; without a checkpoint commit, operators can't
        // see "this commit is when we entered ProofFormalization").
        assert_eq!(
            outcome.commands,
            vec![ProtocolCommand::CommitCheckpoint],
            "human-approved phase advance must emit CommitCheckpoint"
        );
        // Phase-startup routing handoff: the next StartCycle must issue a
        // Review (not a Worker), so the reviewer chooses next_active,
        // must_close_active, allow_new_obligations, etc. for the first
        // burst of ProofFormalization.
        assert!(
            outcome.state.post_advance_routing_pending,
            "human-approved phase advance must set post_advance_routing_pending"
        );
    }

    /// Amendment 6 (add-targets audit): the AdvancePhase freeze must not let
    /// the empty-string incomplete-observation sentinel (the
    /// `observe_paper_faithfulness_fingerprints` fallback) overwrite a good
    /// approved paper pin. Per-target defer: an empty live fp keeps the
    /// existing non-empty approved pin; a non-empty live fp freezes normally;
    /// a never-observed target (empty live fp, no non-empty pin) keeps the
    /// historical empty-freeze behavior.
    #[test]
    fn advance_freeze_defers_empty_live_paper_fingerprint_over_approved_pin() {
        let mut state = base_state();
        state.configured_targets = set(&["t", "t2", "t3"]);
        // t: real live observation -> frozen normally.
        state
            .live
            .paper_current_fingerprints
            .insert("t".into(), "a=fresh".into());
        state
            .paper_approved_fingerprints
            .insert("t".into(), "a=stale".into());
        // t2: transient observation failure (empty live fp) with a good
        // approved pin -> the pin survives the freeze.
        state
            .live
            .paper_current_fingerprints
            .insert("t2".into(), String::new());
        state
            .paper_approved_fingerprints
            .insert("t2".into(), "good-pin".into());
        // t3: never observed, never pinned -> empty freeze (historical
        // behavior preserved).
        state
            .live
            .paper_current_fingerprints
            .insert("t3".into(), String::new());
        state.paper_approved_fingerprints.remove("t3");

        freeze_approved_target_snapshot_from_live(&mut state);

        assert_eq!(
            state
                .paper_approved_fingerprints
                .get("t")
                .map(String::as_str),
            Some("a=fresh"),
            "non-empty live fp freezes normally"
        );
        assert_eq!(
            state
                .paper_approved_fingerprints
                .get("t2")
                .map(String::as_str),
            Some("good-pin"),
            "empty-sentinel live fp must NOT overwrite a good approved pin"
        );
        assert_eq!(
            state
                .paper_approved_fingerprints
                .get("t3")
                .map(String::as_str),
            Some(""),
            "never-observed target keeps the historical empty freeze"
        );
    }

    /// Amendment 6 companion pin: a clean mirror capture precedes the
    /// AdvancePhase approval, so no post-advance LastClean rewind can strand
    /// ProofFormalization with a configured target missing from the restored
    /// coverage maps. The reviewer's AdvancePhase decision calls
    /// `commit_live()` (clean by AdvancePhase legality => the `last_clean_*`
    /// mirrors capture there) BEFORE raising the gate; the HumanGate approve
    /// then enters ProofFormalization. A LastClean reset from inside PF must
    /// restore a state that still covers every configured target and passes
    /// `validate()`.
    #[test]
    fn clean_mirror_capture_precedes_advance_phase_approval() {
        let mut state = base_state();
        // base_state is all-Pass/clean; make the run mirror-populated once
        // so allowed paths exist, then drive the REAL gate-raise path.
        state.phase = Phase::TheoremStating;
        state.stage = Stage::Reviewer;
        state.cycle = 5;
        state.retry_outcome_kind = RetryOutcomeKind::None;
        let request = issue_request_for_test(&mut state, RequestKind::Review);
        assert!(
            request
                .allowed_decisions
                .contains(&ReviewDecisionKind::AdvancePhase),
            "test setup: AdvancePhase must be a legal decision"
        );
        let response = ReviewResponse {
            request_id: request.id,
            cycle: 5,
            status: ResponseStatus::Ok,
            decision: ReviewDecisionKind::AdvancePhase,
            reset: ResetChoice::None,
            next_active: None,
            next_mode: TaskMode::Global,
            ..ReviewResponse::default()
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Review(response),
            },
        )
        .expect("AdvancePhase review applies");
        let state = outcome.state;
        // The gate-raise path captured the clean mirrors BEFORE the gate:
        // every configured target's coverage is in the LastClean mirror.
        assert!(
            state.last_clean_mirrors_populated(),
            "the AdvancePhase gate raise must capture the clean mirrors"
        );
        for target in &state.configured_targets {
            assert!(
                state.last_clean_live.coverage.contains_key(target),
                "clean mirror must cover configured target {target}"
            );
        }

        // Approve the gate (whether the decision auto-advanced or raised
        // HumanGate, PF must be reachable with the mirror already captured).
        let mut state = state;
        if state.stage == Stage::HumanGate {
            let request = issue_request_for_test(&mut state, RequestKind::HumanGate);
            let outcome = apply_event(
                state,
                ProtocolEvent::WrapperResponse {
                    response: WrapperResponse::HumanGate(HumanGateResponse {
                        request_id: request.id,
                        cycle: request.cycle,
                        status: ResponseStatus::Ok,
                        choice: HumanChoice::Approve,
                    }),
                },
            )
            .expect("HumanGate approve applies");
            state = outcome.state;
        }
        assert_eq!(state.phase, Phase::ProofFormalization);

        // A LastClean rewind from PF restores a state that still covers
        // every configured target — no stranded uncovered target.
        let mut rewound = state.clone();
        assert_eq!(
            rewound.apply_last_clean_reset(),
            Ok(true),
            "LastClean must be applicable after the advance"
        );
        assert_eq!(rewound.phase, Phase::ProofFormalization);
        assert_eq!(rewound.configured_targets, state.configured_targets);
        for target in &rewound.configured_targets {
            assert!(
                rewound.live.coverage.contains_key(target),
                "restored coverage must include configured target {target}"
            );
        }
        rewound
            .validate()
            .expect("post-rewind state must pass validate()");
    }

    /// Build the unfalsifiable-pass defect state: `needs_sound` node "a"
    /// carries a soundness Pass pinned to an EMPTY fingerprint (empty
    /// stored assessment parts, empty current fingerprint — the state an
    /// uncomputable strict fingerprint produces). Such a Pass raises no
    /// Soundness blocker and can never go stale, so without the guard the
    /// AdvancePhase human gate armed on a verdict no staleness guard can
    /// ever falsify.
    fn empty_fingerprint_sound_pass_state() -> ProtocolState {
        let mut state = base_state();
        state.phase = Phase::TheoremStating;
        state.stage = Stage::Reviewer;
        state.cycle = 5;
        state.retry_outcome_kind = RetryOutcomeKind::None;
        state
            .live
            .sound_current_fingerprints
            .insert("a".into(), String::new());
        state
            .sound_approved_fingerprints
            .insert("a".into(), String::new());
        state.sound_assessments.insert(
            "a".into(),
            SoundAssessment {
                status: SoundAssessmentStatus::VerifierPass,
                origin: AssessmentOrigin::VerifierPanel,
                fingerprints: SoundFingerprintParts::default(),
                lane_votes: BTreeMap::new(),
                reviewer_action_id: None,
            },
        );
        state.committed = state.live.clone();
        // Defect preconditions hold: the empty-fingerprint Pass is invisible
        // to the blocker set (this is exactly how the gate armed on
        // unfalsifiable passes).
        assert!(state.needs_sound(&NodeId::from("a")));
        assert!(state.current_sound_pass(&NodeId::from("a")));
        assert!(state.global_blockers().is_empty());
        state
    }

    /// Unfalsifiable-pass guard, PRIMARY (legality) path: an AdvancePhase
    /// offered in the defect state is rejected by review-response legality
    /// — the reviewer gets a named rejection reason and a re-issued Review
    /// request, the phase does not advance, and the human gate does not
    /// arm. A hard apply error here would instead fail the burst
    /// (`RuntimeError::Kernel`) and retry-loop, so `apply_event` must
    /// return Ok with the graceful re-prompt.
    #[test]
    fn advance_phase_with_empty_fingerprint_sound_pass_reprompts_reviewer() {
        let mut state = empty_fingerprint_sound_pass_state();
        let request = issue_request_for_test(&mut state, RequestKind::Review);
        assert!(
            request
                .allowed_decisions
                .contains(&ReviewDecisionKind::AdvancePhase),
            "test setup: the reviewer is offered AdvancePhase (blockers empty)"
        );
        let response = ReviewResponse {
            request_id: request.id,
            cycle: 5,
            status: ResponseStatus::Ok,
            decision: ReviewDecisionKind::AdvancePhase,
            reset: ResetChoice::None,
            next_active: None,
            next_mode: TaskMode::Global,
            ..ReviewResponse::default()
        };
        // The legality pair rejects and names the clause.
        assert!(
            !state.review_response_legal(&response),
            "AdvancePhase must be illegal while a needs_sound node holds an \
             empty-fingerprint Pass"
        );
        let reasons = state.review_response_rejection_reasons(&response);
        assert!(
            reasons.iter().any(|r| r.contains("soundness fingerprint")),
            "the rejection must name the empty-fingerprint clause, got: {reasons:?}"
        );
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Review(response),
            },
        )
        .expect("an illegal AdvancePhase must re-prompt the reviewer, not error the apply");
        assert_eq!(
            outcome.state.phase,
            Phase::TheoremStating,
            "the phase must not advance"
        );
        assert_eq!(outcome.state.stage, Stage::Reviewer);
        assert_eq!(
            outcome.state.gate_kind,
            GateKind::None,
            "the human gate must not arm on an unfalsifiable pass"
        );
        assert!(
            outcome
                .state
                .latest_review_rejection_reasons
                .iter()
                .any(|r| r.contains("soundness fingerprint")),
            "the re-issued request must carry the named reason, got: {:?}",
            outcome.state.latest_review_rejection_reasons
        );
        assert!(
            outcome.commands.iter().any(|command| matches!(
                command,
                ProtocolCommand::IssueRequest { request, .. } if request.kind == RequestKind::Review
            )),
            "a fresh Review request must be re-issued"
        );
    }

    /// Unfalsifiable-pass guard, apply-time BACKSTOP: the legality clause
    /// above makes this unreachable through `apply_review_response`, but
    /// the apply arm keeps its own check as defense in depth. Drive
    /// `apply_theorem_review_response` directly (bypassing the legality
    /// gate) and require the hard rejection.
    #[test]
    fn advance_phase_apply_backstop_rejects_empty_fingerprint_sound_pass() {
        let mut state = empty_fingerprint_sound_pass_state();
        let request = issue_request_for_test(&mut state, RequestKind::Review);
        let response = ReviewResponse {
            request_id: request.id,
            cycle: 5,
            status: ResponseStatus::Ok,
            decision: ReviewDecisionKind::AdvancePhase,
            reset: ResetChoice::None,
            next_active: None,
            next_mode: TaskMode::Global,
            ..ReviewResponse::default()
        };
        let error = apply_theorem_review_response(&mut state, response).expect_err(
            "the apply-time backstop must reject AdvancePhase while a needs_sound \
             node holds an empty-fingerprint Pass",
        );
        assert!(
            matches!(error, TransitionError::IllegalReviewerDecision),
            "expected IllegalReviewerDecision, got: {error:?}"
        );
    }

    #[test]
    fn human_gate_rejection_returns_to_pre_gate_phase() {
        // Step 12 (revision_plan.md §11): a rejected Advance gate must return
        // to the PRE-GATE phase, not a hard-coded TheoremStating. A rejected
        // RevisionStating gate returns to RevisionStating review; a rejected
        // TheoremStating gate still returns to TheoremStating (no regression).
        for (origin_phase, expect_phase) in [
            (Phase::RevisionStating, Phase::RevisionStating),
            (Phase::TheoremStating, Phase::TheoremStating),
        ] {
            let mut state = base_state();
            state.phase = origin_phase;
            state.stage = Stage::HumanGate;
            state.cycle = 10;
            state.gate_kind = GateKind::Advance;
            let request = issue_request_for_test(&mut state, RequestKind::HumanGate);

            let outcome = apply_event(
                state,
                ProtocolEvent::WrapperResponse {
                    response: WrapperResponse::HumanGate(HumanGateResponse {
                        request_id: request.id,
                        cycle: 10,
                        status: ResponseStatus::Ok,
                        choice: HumanChoice::Feedback,
                    }),
                },
            )
            .unwrap();
            assert_eq!(
                outcome.state.phase, expect_phase,
                "rejected {origin_phase:?} gate must return to {expect_phase:?}"
            );
            assert_eq!(outcome.state.stage, Stage::Reviewer);
            assert!(outcome.state.human_input_outstanding);
            assert_eq!(outcome.state.gate_kind, GateKind::None);
            match outcome.commands.as_slice() {
                [ProtocolCommand::IssueRequest { request }] => {
                    assert_eq!(request.kind, RequestKind::Review);
                    assert_eq!(request.phase, expect_phase);
                }
                other => panic!("expected a single Review request, got {other:?}"),
            }
        }
    }

    #[test]
    fn human_approve_advance_from_revision_stating_enters_proof_formalization() {
        // Step 12: an approved RevisionStating gate advances to
        // ProofFormalization, snapshots coarse_dag_nodes from present nodes,
        // and preserves the RevisionContext as historical metadata (revision
        // edit-scoping is selected only in RevisionStating, so it stops here).
        let mut state = base_state();
        state.phase = Phase::RevisionStating;
        state.stage = Stage::HumanGate;
        state.cycle = 10;
        state.gate_kind = GateKind::Advance;
        let mut ctx = crate::model::RevisionContext::default();
        ctx.frozen_nodes = set(&["b"]);
        ctx.editable_nodes = set(&["a"]);
        state.revision_context = Some(ctx.clone());
        let request = issue_request_for_test(&mut state, RequestKind::HumanGate);

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::HumanGate(HumanGateResponse {
                    request_id: request.id,
                    cycle: 10,
                    status: ResponseStatus::Ok,
                    choice: HumanChoice::Approve,
                }),
            },
        )
        .unwrap();
        assert_eq!(outcome.state.phase, Phase::ProofFormalization);
        assert_eq!(outcome.state.stage, Stage::Start);
        // coarse_dag_nodes snapshotted from present nodes (theorem-stating
        // transition behavior).
        assert_eq!(outcome.state.coarse_dag_nodes, set(&["a", "b"]));
        // RevisionContext preserved as historical metadata.
        assert_eq!(outcome.state.revision_context, Some(ctx));
        assert_eq!(outcome.commands, vec![ProtocolCommand::CommitCheckpoint]);
    }

    #[test]
    fn human_approve_advance_issues_review_not_worker() {
        // Phase-startup routing: after a human-approved phase advance
        // into ProofFormalization, the very next StartCycle must dispatch
        // a Review request (not a Worker). The reviewer's allowed_decisions
        // is `{Continue, NeedInput}` here (no AdvancePhase — see
        // `request_allowed_decisions`'s ProofFormalization arm); the
        // reviewer is expected to choose `next_active`, `next_mode`,
        // `must_close_active`, `allow_new_obligations`, etc. for the first
        // burst of the new phase.
        let mut state = base_state();
        state.stage = Stage::HumanGate;
        state.cycle = 10;
        state.configured_targets = set(&["t"]);
        state.gate_kind = GateKind::Advance;
        state
            .live
            .target_fingerprints
            .insert("a".into(), "ct-live-node".into());
        state
            .live
            .paper_current_fingerprints
            .insert("t".into(), "a=ct-live-node".into());
        let request = issue_request_for_test(&mut state, RequestKind::HumanGate);

        let approve_outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::HumanGate(HumanGateResponse {
                    request_id: request.id,
                    cycle: 10,
                    status: ResponseStatus::Ok,
                    choice: HumanChoice::Approve,
                }),
            },
        )
        .unwrap();
        assert_eq!(approve_outcome.state.phase, Phase::ProofFormalization);
        assert_eq!(approve_outcome.state.stage, Stage::Start);
        assert!(approve_outcome.state.post_advance_routing_pending);

        let started = apply_event(approve_outcome.state, ProtocolEvent::StartCycle).unwrap();
        assert_eq!(started.state.stage, Stage::Reviewer);
        assert!(
            started.state.post_advance_routing_pending,
            "latch persists through the in-flight routing Review so the \
             in-flight invariant check keeps holding; it clears in \
             apply_proof_review_response when the response is applied"
        );
        let request = started
            .state
            .in_flight_request
            .as_ref()
            .expect("post-advance StartCycle must issue a request");
        assert_eq!(
            request.kind,
            RequestKind::Review,
            "post-advance StartCycle must issue Review, not Worker"
        );
        assert!(
            request.post_advance_routing,
            "the routing Review's WrapperRequest must carry post_advance_routing=true"
        );
        // The whole point of leaving `active_coarse_node = None` at
        // phase entry is so the routing Review has full latitude.
        // Verify the kernel surfaces every open coarse-DAG node as a
        // candidate (per `30b_coarse_anchor.md`), and that the
        // active-node hint is not narrowed to a single anchor's cone.
        assert!(
            !request.kernel_hinted_next_active_coarse_nodes.is_empty(),
            "post-advance routing Review must surface non-empty \
             kernel_hinted_next_active_coarse_nodes so the reviewer can \
             pick `next_active_coarse` from all open coarse nodes; got empty",
        );
        assert!(
            !request.kernel_hinted_next_active_nodes.is_empty(),
            "post-advance routing Review must surface non-empty \
             kernel_hinted_next_active_nodes; pre-seeding an anchor would \
             have narrowed this to a cone and defeated routing",
        );
    }

    #[test]
    fn post_advance_review_does_not_allow_advance_phase() {
        // The post-advance routing Review must NOT permit AdvancePhase
        // (the operator just signed off on advancing — re-advancing here
        // would be nonsense). Continue is required so the reviewer can
        // route the first worker burst; NeedInput is allowed so escalation
        // is still possible. AdvancePhase must be excluded.
        let mut state = base_state();
        state.stage = Stage::HumanGate;
        state.cycle = 10;
        state.configured_targets = set(&["t"]);
        state.gate_kind = GateKind::Advance;
        state
            .live
            .target_fingerprints
            .insert("a".into(), "ct-live-node".into());
        state
            .live
            .paper_current_fingerprints
            .insert("t".into(), "a=ct-live-node".into());
        let request = issue_request_for_test(&mut state, RequestKind::HumanGate);

        let approve_outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::HumanGate(HumanGateResponse {
                    request_id: request.id,
                    cycle: 10,
                    status: ResponseStatus::Ok,
                    choice: HumanChoice::Approve,
                }),
            },
        )
        .unwrap();
        let started = apply_event(approve_outcome.state, ProtocolEvent::StartCycle).unwrap();
        let request = started
            .state
            .in_flight_request
            .as_ref()
            .expect("post-advance StartCycle must issue a request");
        assert_eq!(request.kind, RequestKind::Review);
        assert!(
            !request
                .allowed_decisions
                .contains(&ReviewDecisionKind::AdvancePhase),
            "post-advance routing Review must NOT allow AdvancePhase"
        );
        assert!(
            request
                .allowed_decisions
                .contains(&ReviewDecisionKind::Continue),
            "post-advance routing Review must allow Continue so the reviewer can route the first worker burst"
        );
    }

    #[test]
    fn post_advance_review_response_routes_worker_normally() {
        // Phase-startup routing end-to-end: the reviewer's Continue with
        // `next_active=Some(...)`, `must_close_active=true`,
        // `allow_new_obligations=false` must seed the next worker burst
        // with those flags exactly — the standard `apply_proof_review_response`
        // routing path handles this once `post_advance_routing_pending`
        // has fired the Review on phase entry.
        let mut state = base_state();
        // Drop "b" — base_state seeds it as a present but un-covered
        // sibling, which `orphan_cleanup_needed` would otherwise pick up
        // on the post-Review StartCycle, overwriting the reviewer's
        // pending_task with an orphan-cleanup task. The post-advance
        // routing semantics we want to verify are about the reviewer's
        // flags flowing into the dispatched worker — orphan cleanup is a
        // separate pre-emption path tested elsewhere.
        state.live.present_nodes = set(&["a"]);
        state.live.open_nodes = set(&["a"]);
        state.stage = Stage::HumanGate;
        state.cycle = 10;
        state.configured_targets = set(&["t"]);
        state.gate_kind = GateKind::Advance;
        state
            .live
            .target_fingerprints
            .insert("a".into(), "ct-live-node".into());
        state
            .live
            .paper_current_fingerprints
            .insert("t".into(), "a=ct-live-node".into());
        // Keep committed in sync with the trimmed live so the
        // validate() post-condition holds.
        state.committed = state.live.clone();
        let request = issue_request_for_test(&mut state, RequestKind::HumanGate);

        let approve_outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::HumanGate(HumanGateResponse {
                    request_id: request.id,
                    cycle: 10,
                    status: ResponseStatus::Ok,
                    choice: HumanChoice::Approve,
                }),
            },
        )
        .unwrap();

        let started = apply_event(approve_outcome.state, ProtocolEvent::StartCycle).unwrap();
        let review_request = started
            .state
            .in_flight_request
            .as_ref()
            .expect("post-advance StartCycle must issue a request")
            .clone();
        assert_eq!(review_request.kind, RequestKind::Review);
        let cycle_at_review = started.state.cycle;

        // Reviewer routes the first worker burst with explicit
        // `must_close_active=true, allow_new_obligations=false` (the
        // strict combo project memory prefers over the kernel default).
        let (paper_focus_ranges, paper_grounding) = test_paper_grounding();
        let response_outcome = apply_event(
            started.state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Review(ReviewResponse {
                    request_id: review_request.id,
                    cycle: cycle_at_review,
                    status: ResponseStatus::Ok,
                    decision: ReviewDecisionKind::Continue,
                    // Pin to the kernel-seeded initial active node "a" —
                    // by base_state, only "a" is a `proof_node` and the
                    // single configured target's coverage, so it's the
                    // sole legal next_active candidate post-Approve.
                    next_active: Some("a".into()),
                    next_mode: TaskMode::Local,
                    must_close_active: true,
                    allow_new_obligations: false,
                    paper_focus_ranges,
                    paper_grounding,
                    ..ReviewResponse::default()
                }),
            },
        )
        .expect("apply post-advance routing review");

        // Reviewer-Continue lands the state at Stage::Start with the
        // reviewer's `pending_task` seeded (`apply_proof_review_response`
        // installs node/must_close_active/allow_new_obligations into
        // `state.pending_task`). The next StartCycle dispatches the
        // Worker. Drive that next cycle and assert the dispatched worker
        // request carries the reviewer's explicit flags.
        assert_eq!(response_outcome.state.stage, Stage::Start);
        // Validate the reviewer's pending_task survived through the Continue.
        let pending = response_outcome
            .state
            .pending_task
            .as_ref()
            .expect("reviewer Continue must seed pending_task");
        assert!(
            pending.must_close_active,
            "reviewer's must_close_active must land in pending_task (got pending_task={:?})",
            pending,
        );
        assert!(
            !pending.allow_new_obligations,
            "reviewer's allow_new_obligations must land in pending_task"
        );
        let worker_started = apply_event(response_outcome.state, ProtocolEvent::StartCycle)
            .expect("StartCycle after post-advance review should dispatch worker");
        assert_eq!(worker_started.state.stage, Stage::Worker);
        let worker_request = worker_started
            .commands
            .iter()
            .find_map(|c| match c {
                ProtocolCommand::IssueRequest { request }
                    if request.kind == RequestKind::Worker =>
                {
                    Some(request)
                }
                _ => None,
            })
            .expect("post-advance routing Review Continue must dispatch a Worker request");
        assert_eq!(worker_request.active_node.as_deref(), Some("a"));
        assert!(
            worker_request.worker_context.must_close_active,
            "reviewer's must_close_active must propagate to the dispatched worker"
        );
        assert!(
            !worker_request.worker_context.allow_new_obligations,
            "reviewer's allow_new_obligations must propagate to the dispatched worker"
        );
    }

    #[test]
    fn human_approve_advance_snapshots_protected_closure_from_live_per_target_slot() {
        // Audit follow-up (2026-05-03 protected-closure widening): the
        // live observation slot `protected_closure_nodes_per_target` is
        // populated by worker bursts (see
        // `runtime_cli.rs:populate_response_fingerprints`). At
        // AdvancePhase Approve the engine must (a) union the per-target
        // closures, (b) drop Preamble defensively (the observation
        // helper already filters but engine belt-and-braces it), and
        // (c) drop nodes already in `coverage` (those live in
        // `approved_targets.coverage`, not in `protected_closure_nodes`).
        let mut state = base_state();
        state.stage = Stage::HumanGate;
        state.cycle = 10;
        state.configured_targets = set(&["t1", "t2"]);
        state.gate_kind = GateKind::Advance;
        // Coverage requires matching target_claims for the validate()
        // post-condition that runs at the end of apply_event ("live
        // coverage must be derived from target claims"). Set both
        // sides for each covering node.
        state.live.present_nodes.insert("Cov1".into());
        state.live.present_nodes.insert("Cov2".into());
        state.target_claims.insert("Cov1".into(), set(&["t1"]));
        state.target_claims.insert("Cov2".into(), set(&["t2"]));
        state
            .live
            .target_fingerprints
            .insert("Cov1".into(), "fp-cov1".into());
        state
            .live
            .target_fingerprints
            .insert("Cov2".into(), "fp-cov2".into());
        state
            .live
            .paper_current_fingerprints
            .insert("t1".into(), "Cov1=fp-cov1".into());
        state
            .live
            .paper_current_fingerprints
            .insert("t2".into(), "Cov2=fp-cov2".into());
        state.live.coverage.insert("t1".into(), set(&["Cov1"]));
        state.live.coverage.insert("t2".into(), set(&["Cov2"]));
        // Closure populated by the most recent worker observation.
        // - t1's closure: Helper, Shared
        // - t2's closure: Shared, Cov1 (already in coverage), Preamble (defensive drop)
        // Expected post-Approve set: {Helper, Shared}.
        state
            .live
            .protected_closure_nodes_per_target
            .insert("t1".into(), set(&["Helper", "Shared"]));
        state
            .live
            .protected_closure_nodes_per_target
            .insert("t2".into(), set(&["Shared", "Cov1", "Preamble"]));
        // Mirror committed = live so the validate() post-condition
        // ("committed coverage must be derived from target claims")
        // passes — the existing test infra normally relies on
        // `commit_live()` having run on a prior cycle, but here we're
        // hand-building an HumanGate state without prior cycles.
        state.committed = state.live.clone();
        state.committed_target_claims = state.target_claims.clone();
        state.committed_node_kinds = state.node_kinds.clone();
        state.committed_proof_nodes = state.proof_nodes.clone();
        state.committed_deps = state.deps.clone();
        let request = issue_request_for_test(&mut state, RequestKind::HumanGate);

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::HumanGate(HumanGateResponse {
                    request_id: request.id,
                    cycle: 10,
                    status: ResponseStatus::Ok,
                    choice: HumanChoice::Approve,
                }),
            },
        )
        .unwrap();
        assert_eq!(outcome.state.phase, Phase::ProofFormalization);
        assert_eq!(
            outcome.state.approved_targets.coverage.get("t1"),
            Some(&set(&["Cov1"]))
        );
        assert_eq!(
            outcome.state.approved_targets.coverage.get("t2"),
            Some(&set(&["Cov2"]))
        );
        assert_eq!(
            outcome.state.approved_targets.protected_closure_nodes,
            set(&["Helper", "Shared"]),
            "engine should snapshot the closure union, drop covering nodes (Cov1) and Preamble"
        );
        // The widened protection set surfaces through approved_target_nodes()
        // — the worker-acceptance reopen guard reads this set.
        assert_eq!(
            outcome.state.approved_target_nodes(),
            set(&["Cov1", "Cov2", "Helper", "Shared"]),
            "approved_target_nodes() must be coverage union the protected closure"
        );
    }

    #[test]
    fn human_approve_advance_freezes_pv_spec_role_nodes_into_protected_set() {
        // PV Phase 8 slice 1: a present spec-role node ({Spec, Safety,
        // Correctness, Invariant}) with NO paper target must be frozen into
        // `protected_closure_nodes` at AdvancePhase Approve and thus land in
        // `approved_target_nodes()` — without it a PV tablet's
        // proposition-bearing nodes would never enter the worker-acceptance
        // protection set / the `protected_semantic_change_nodes` legality
        // membership (a weakened-postcondition re-approval could slip).
        let mut state = base_state();
        state.stage = Stage::HumanGate;
        state.cycle = 11;
        state.configured_targets = set(&["t1"]);
        state.gate_kind = GateKind::Advance;
        // One ordinary paper target + covering node (the all-math machinery).
        state.live.present_nodes.insert("Cov1".into());
        state.target_claims.insert("Cov1".into(), set(&["t1"]));
        state
            .live
            .target_fingerprints
            .insert("Cov1".into(), "fp-cov1".into());
        state
            .live
            .paper_current_fingerprints
            .insert("t1".into(), "Cov1=fp-cov1".into());
        state.live.coverage.insert("t1".into(), set(&["Cov1"]));
        // The PV spec node: present, Correctness role, claims no paper target.
        state.live.present_nodes.insert("GcdCorrect".into());
        state
            .node_role
            .insert("GcdCorrect".into(), PvRole::Correctness);
        // A non-gated role node (ExtractionModel) is excluded from the spec
        // freeze (it is byte-pinned / Phase-2-protected, not a proposition).
        state.live.present_nodes.insert("gcdModel".into());
        state
            .node_role
            .insert("gcdModel".into(), PvRole::ExtractionModel);
        state.committed = state.live.clone();
        state.committed_target_claims = state.target_claims.clone();
        state.committed_node_kinds = state.node_kinds.clone();
        state.committed_proof_nodes = state.proof_nodes.clone();
        state.committed_deps = state.deps.clone();
        let request = issue_request_for_test(&mut state, RequestKind::HumanGate);

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::HumanGate(HumanGateResponse {
                    request_id: request.id,
                    cycle: 11,
                    status: ResponseStatus::Ok,
                    choice: HumanChoice::Approve,
                }),
            },
        )
        .unwrap();
        assert_eq!(outcome.state.phase, Phase::ProofFormalization);
        assert!(
            outcome
                .state
                .approved_targets
                .protected_closure_nodes
                .contains(&NodeId::from("GcdCorrect")),
            "a present Correctness-role node must freeze into protected_closure_nodes"
        );
        assert!(
            !outcome
                .state
                .approved_targets
                .protected_closure_nodes
                .contains(&NodeId::from("gcdModel")),
            "a non-gated role (ExtractionModel) must NOT enter the spec freeze"
        );
        assert!(
            outcome
                .state
                .approved_target_nodes()
                .contains(&NodeId::from("GcdCorrect")),
            "the frozen spec node must surface through approved_target_nodes()"
        );
    }

