        state.corr_approved_fingerprints.remove("c");
        state
            .live
            .corr_current_fingerprints
            .insert("c".into(), "cc".into());
        mark_substantiveness_pass(&mut state, "c", "sub-c");

        let request = issue_request_for_test(&mut state, RequestKind::Review);
