    // ===== PV "prove OR disprove" (Decide pairs) =====================

    /// Seed a `Decide` pair (`goal:correct` / `goal:correct__refutation`) into a
    /// state, with a present node `Correct` claiming the primary. Mode-B PV.
    fn decide_pair_state() -> ProtocolState {
        let mut state = base_state();
        state.pv_tablet_configured = true;
        let primary = trellis_kernel::ChallengeTargetId::from("goal:correct");
        let refutation = trellis_kernel::refutation_target_id(&primary);
        let primary_spec = trellis_kernel::ChallengeTargetSpec {
            kind: trellis_kernel::ChallengeTargetKind::Theorem,
            name: "Correct".to_string(),
            lean: "theorem Correct (x : I32) (h : Pre x) : f x ⦃ ret => Spec x ret ⦄ := by"
                .to_string(),
            resolution: trellis_kernel::ChallengeResolution::Decide,
            ..trellis_kernel::ChallengeTargetSpec::default()
        };
        let refutation_lean =
            trellis_kernel::refutation_statement(&primary_spec).expect("refutation");
        let refutation_spec = trellis_kernel::ChallengeTargetSpec {
            kind: trellis_kernel::ChallengeTargetKind::Theorem,
            name: trellis_kernel::refutation_node_name("Correct"),
            lean: refutation_lean,
            ..trellis_kernel::ChallengeTargetSpec::default()
        };
        state
            .configured_challenge_targets
            .insert(primary.clone(), primary_spec);
        state
            .configured_challenge_targets
            .insert(refutation.clone(), refutation_spec);
        state.live.present_nodes.insert("Correct".into());
        state.proof_nodes.insert("Correct".into());
        // The real mode-B seed (`seed_state_from_config`) registers
        // `node_kinds` + `deps` + `challenge_claims` for every challenge node;
        // mirror that here so the fixture is a state the runtime can actually
        // produce (`validate()` enforces it for Decide-pair nodes).
        state.deps.insert("Correct".into(), BTreeSet::new());
        state.challenge_claims.insert(
            "Correct".into(),
            set(&["goal:correct"]).into_iter().collect(),
        );
        state.active_node = Some("Correct".into());
        state.normalize_all_structural_state();
        state.ensure_node_metadata();
        state
    }

    fn rust_witness_response_for_decide_pair(
        state: &ProtocolState,
        source: &str,
        receipt_label: &[u8],
    ) -> WorkerResponse {
        let target = trellis_kernel::ChallengeTargetId::from("goal:correct");
        let relative_path = trellis_kernel::trust_base::rust_witness_relative_path(&target);
        let runner_sha256 = trellis_kernel::trust_base::raw_sha256(b"generic-runner");
        let artifact_sha256 = trellis_kernel::trust_base::raw_sha256(source.as_bytes());
        let pinned_crate_tree_sha256 =
            trellis_kernel::trust_base::raw_sha256(b"generic-crate");
        let runner_request = serde_json::json!({
            "target_id": target,
            "relative_path": relative_path,
            "artifact_sha256": artifact_sha256,
            "pinned_crate_tree_sha256": pinned_crate_tree_sha256,
            "cargo_lock_sha256": trellis_kernel::trust_base::raw_sha256(receipt_label),
            "goal_sha256": trellis_kernel::trust_base::raw_sha256(b"generic-goal"),
            "rustc_vv": "rustc generic fixture\n",
        });
        let runner_output = serde_json::json!({
            "schema": trellis_kernel::trust_base::RUST_WITNESS_RUNNER_OUTPUT_SCHEMA,
            "status": "available",
            "attempted": true,
            "target_id": runner_request["target_id"],
            "relative_path": runner_request["relative_path"],
            "artifact_sha256": runner_request["artifact_sha256"],
            "pinned_crate_tree_sha256": runner_request["pinned_crate_tree_sha256"],
            "cargo_lock_sha256": runner_request["cargo_lock_sha256"],
            "goal_sha256": runner_request["goal_sha256"],
            "rustc_vv": runner_request["rustc_vv"],
            "timed_out": false,
            "exit_code": 0,
            "stdout_base64": "",
            "stderr_base64": "",
            "stdout_sha256": trellis_kernel::trust_base::raw_sha256(b""),
            "stderr_sha256": trellis_kernel::trust_base::raw_sha256(b""),
            "stdout_truncated": false,
            "stderr_truncated": false,
        });
        let mut execution_receipt = serde_json::json!({
            "schema": "trellis-checked-execution-receipt/v1",
            "purpose": trellis_kernel::trust_base::RUST_WITNESS_EXECUTION_PURPOSE,
            "tool_logical_id": trellis_kernel::trust_base::RUST_WITNESS_RUNNER_LOGICAL_ID,
            "runner_sha256": runner_sha256,
            "input": runner_request,
            "parsed_stdout": runner_output,
            "receipt_sha256": trellis_kernel::trust_base::Sha256Digest::ZERO,
        });
        let receipt_sha256 = trellis_kernel::trust_base::self_digest(
            trellis_kernel::trust_base::DomainTag::RawArtifact,
            &execution_receipt,
            "receipt_sha256",
        )
        .unwrap();
        execution_receipt["receipt_sha256"] = serde_json::json!(receipt_sha256);
        let declaration = trellis_kernel::trust_base::RustWitnessArtifactDeclaration {
            target_id: target.clone(),
            relative_path: relative_path.clone(),
        };
        let record = trellis_kernel::trust_base::RustWitnessArtifactRecord {
            schema: trellis_kernel::trust_base::RUST_WITNESS_ARTIFACT_SCHEMA.into(),
            target_id: target,
            relative_path,
            artifact_sha256,
            pinned_crate_tree_sha256,
            execution: trellis_kernel::trust_base::RustWitnessExecution::Receipt {
                receipt_sha256,
                runner_sha256,
                timed_out: false,
                exit_code: Some(0),
            },
            correspondence: trellis_kernel::trust_base::RustWitnessCorrespondence::NotReviewed,
            freeze_episode_id: state
                .trust_base
                .advance_gate_episode_id
                .clone()
                .unwrap(),
            gate_episode_id: state
                .trust_base
                .advance_gate_episode_id
                .clone()
                .unwrap(),
        };
        let payload = trellis_kernel::trust_base::RustWitnessArtifactPayload {
            source_utf8: source.into(),
            runner_request: execution_receipt["input"].clone(),
            execution_receipt: Some(execution_receipt),
            correspondence_request: None,
            correspondence_verdict: None,
        };
        WorkerResponse {
            rust_witness_artifact: Some(declaration),
            rust_witness_artifact_record: Some(record),
            rust_witness_artifact_payload: Some(payload),
            ..WorkerResponse::default()
        }
    }

    fn make_rust_witness_fixture_unavailable(response: &mut WorkerResponse) {
        let payload = response.rust_witness_artifact_payload.as_mut().unwrap();
        let receipt = payload.execution_receipt.as_mut().unwrap();
        receipt["parsed_stdout"]["status"] = serde_json::json!("unavailable");
        receipt["parsed_stdout"]["exit_code"] = serde_json::json!(101);
        receipt["parsed_stdout"]["timed_out"] = serde_json::json!(false);
        receipt["receipt_sha256"] =
            serde_json::json!(trellis_kernel::trust_base::Sha256Digest::ZERO);
        let receipt_sha256 = trellis_kernel::trust_base::self_digest(
            trellis_kernel::trust_base::DomainTag::RawArtifact,
            receipt,
            "receipt_sha256",
        )
        .unwrap();
        receipt["receipt_sha256"] = serde_json::json!(receipt_sha256);
        let record = response.rust_witness_artifact_record.as_mut().unwrap();
        record.execution = trellis_kernel::trust_base::RustWitnessExecution::Receipt {
            receipt_sha256,
            runner_sha256: trellis_kernel::trust_base::raw_sha256(b"generic-runner"),
            timed_out: false,
            exit_code: Some(101),
        };
    }

    #[test]
    fn post_approval_artifact_install_and_drift_reopen_protected_reapproval_only() {
        let mut state = decide_pair_state();
        let primary = trellis_kernel::ChallengeTargetId::from("goal:correct");
        let refutation = trellis_kernel::refutation_target_id(&primary);
        let refutation_node = NodeId::from(
            state.configured_challenge_targets[&refutation]
                .name
                .as_str(),
        );
        state
            .pv_live_polarity
            .insert(primary.clone(), trellis_kernel::ChallengePolarity::Disprove);
        let mut closure = LocalClosureRecord::default();
        closure.node = refutation_node.clone();
        state
            .local_closure_records
            .insert(refutation_node.clone(), closure);
        state.trust_base.advance_gate_episode_id = Some("advance:generic".into());
        state.trust_base.routine_gate_state = TrustRoutineGateState::Approved;
        state.trust_base.package_ready = true;
        let polarity_before = state.pv_live_polarity.clone();
        let closure_before = state.local_closure_records.clone();

        let mut first = rust_witness_response_for_decide_pair(
            &state,
            "#[test] fn witness() { println!(\"first\"); }\n",
            b"first-receipt",
        );
        install_rust_witness_artifact(&mut state, &mut first).unwrap();
        assert_eq!(
            state.pending_protected_reapproval_nodes,
            BTreeSet::from([refutation_node.clone()])
        );
        assert!(!state.trust_base.package_ready);
        assert_eq!(state.pv_live_polarity, polarity_before);
        assert_eq!(state.local_closure_records, closure_before);

        // Simulate the prior dossier having completed its approval episode,
        // then install different frozen source/receipt bytes.
        state.pending_protected_reapproval_nodes.clear();
        state.trust_base.pending_rust_witness_correspondence_target = None;
        state.trust_base.package_ready = true;
        let mut drift = rust_witness_response_for_decide_pair(
            &state,
            "#[test] fn witness() { println!(\"drift\"); }\n",
            b"drift-receipt",
        );
        install_rust_witness_artifact(&mut state, &mut drift).unwrap();
        assert_eq!(
            state.pending_protected_reapproval_nodes,
            BTreeSet::from([refutation_node])
        );
        assert!(!state.trust_base.package_ready);
        assert_eq!(state.pv_live_polarity, polarity_before);
        assert_eq!(state.local_closure_records, closure_before);
    }

