    /// Stage 5: unwrap an `Applied` flip outcome (panics on a refusal) —
    /// the pre-precondition tests all exercise non-trust states where every
    /// legal flip still applies unconditionally.
    fn flip_commands(outcome: PolarityFlipOutcome) -> Vec<ProtocolCommand> {
        match outcome {
            PolarityFlipOutcome::Applied(commands) => commands,
            PolarityFlipOutcome::Refused { reason, .. } => {
                panic!("flip unexpectedly refused: {reason}")
            }
        }
    }

