    /// PV under-model (Slice 1): a `decide_pair_state` with a live NeedInput
    /// audit carrying an `under_model_disproof` (the post-state of a reviewer
    /// forwarding a worker `TargetFalseUnderModel` claim to the auditor).
    fn under_model_audit_state() -> ProtocolState {
        let mut state = decide_pair_state();
        seed_assumptions_node_for_test(&mut state);
        state.phase = Phase::ProofFormalization;
        state.stage = Stage::StuckMathAudit;
        state.cycle = 7;
        state.active_node = None;
        state.stuck_math_audit.active = true;
        state.stuck_math_audit.need_input_audit = Some(NeedInputAuditContext {
            phase: Phase::ProofFormalization,
            active_node: Some("Correct".into()),
            mode: TaskMode::Local,
            reviewer_reason: "worker reports T false under the model".into(),
            review_request_id: 1,
            review_cycle: 7,
            under_model_disproof: "x0 = slice of length 2^63 falsifies parse_number".into(),
            under_model_route_opinion: "model-deviation".into(),
            ..NeedInputAuditContext::default()
        });
        state.ensure_node_metadata();
        state
    }

    #[test]
    fn under_model_worker_outcome_routes_to_auditor_via_need_input() {
        // PV under-model (Slice 1, regression b): a `TargetFalseUnderModel`
        // worker outcome is mirrored onto state and reaches the auditor via the
        // reviewer's NeedInput → route_need_input_to_auditor path. Here we drive
        // the two hops: (1) the worker reject mirrors the disproof onto state,
        // (2) the reviewer NeedInput carries it into the audit context.
        let mut state = decide_pair_state();
        state.phase = Phase::ProofFormalization;
        state.stage = Stage::Worker;
        state.cycle = 5;
        state.pending_task = Some(PendingTask::default());
        let request = issue_request_for_test(&mut state, RequestKind::Worker);
        let response = WorkerResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Ok,
            outcome: WorkerOutcome::TargetFalseUnderModel,
            summary: "T is false under the model".into(),
            under_model_disproof: "x0 = over-isize::MAX slice falsifies parse_number".into(),
            under_model_route_opinion: "model-deviation".into(),
            under_model_reasoning: "the Usize→Isize cast wraps negative".into(),
            ..WorkerResponse::default()
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(response),
            },
        )
        .expect("under-model worker outcome must be accepted (routed like NR)");
        let mut state = outcome.state;
        // Hop 1: the disproof is mirrored onto state for the next reviewer.
        assert_eq!(
            state.latest_worker_under_model_disproof,
            "x0 = over-isize::MAX slice falsifies parse_number"
        );
        assert_eq!(
            state.latest_worker_under_model_route_opinion,
            "model-deviation"
        );
        // The worker authored no tablet edit and did not flip polarity.
        let primary = trellis_kernel::ChallengeTargetId::from("goal:correct");
        assert!(state.pv_polarity_flip_count.get(&primary).is_none());

        // Hop 2: the reviewer forwards via NeedInput → the auditor inherits the
        // disproof in its audit context.
        state.stage = Stage::Reviewer;
        state.active_node = Some("Correct".into());
        let review_request = issue_request_for_test(&mut state, RequestKind::Review);
        let mut commands = Vec::new();
        let review = ReviewResponse {
            request_id: review_request.id,
            cycle: review_request.cycle,
            reason: "forwarding the under-model claim to the auditor".into(),
            ..ReviewResponse::default()
        };
        route_need_input_to_auditor(&mut state, &review, &mut commands, false);
        assert_eq!(state.stage, Stage::StuckMathAudit);
        let ctx = state
            .stuck_math_audit
            .need_input_audit
            .as_ref()
            .expect("audit context set");
        assert_eq!(
            ctx.under_model_disproof, "x0 = over-isize::MAX slice falsifies parse_number",
            "the auditor must inherit the worker's disproof"
        );
        assert_eq!(ctx.under_model_route_opinion, "model-deviation");
        assert_eq!(
            first_issued_request(&commands).kind,
            RequestKind::StuckMathAudit
        );
    }

    #[test]
    fn under_model_auditor_bug_ruling_flips_to_disprove() {
        // PV under-model (Slice 1, regression c): the auditor's "bug" ruling
        // flips polarity to Disprove (the sole flip site, authorized by the
        // adjudication) and returns to the Reviewer.
        let mut state = under_model_audit_state();
        let primary = trellis_kernel::ChallengeTargetId::from("goal:correct");
        let polarity_before = state.live_polarity(&primary);
        let request = issue_request_for_test(&mut state, RequestKind::StuckMathAudit);
        let response = StuckMathAuditResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Ok,
            confirm_need_input: true,
            report: "## Claim being audited\n".to_string()
                + &"x".repeat(AUDIT_REPORT_TEXT_MIN_CHARS),
            under_model_ruling: "bug".into(),
            ..StuckMathAuditResponse::default()
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("under-model bug ruling must flip and return to reviewer");
        assert_ne!(
            outcome.state.live_polarity(&primary),
            polarity_before,
            "a bug ruling must flip polarity"
        );
        assert_eq!(
            outcome.state.live_polarity(&primary),
            trellis_kernel::ChallengePolarity::Disprove
        );
        assert_eq!(
            outcome.state.pv_polarity_flip_count.get(&primary).copied(),
            Some(1)
        );
        assert_eq!(outcome.state.stage, Stage::Reviewer);
        assert!(outcome.state.stuck_math_audit.need_input_audit.is_none());
    }

    #[test]
    fn lane_pass_under_a_need_input_plan_retires_the_plan_with_the_latch() {
        // dec2flt cycle-280 regression: a need-input audit plan named an
        // authoring candidate, the reviewer enacted it, and the lane's pass
        // verdict reset the audit latch while the latch-coupled plan was
        // still live — validate tripped "need_input_audit plan requires
        // active stuck_math_audit latch" and the supervisor died
        // mid-transition. The latch reset must retire such a plan to the
        // snapshot surface.
        let mut state = approach_audit_state();
        state.stuck_math_audit.assumptions_lane = Some(AssumptionsLaneContext {
            assumption_id: "slice_admissibility".into(),
            candidate_invariant: "tail slices of valid slices are admissible".into(),
            axiom_name: "RustValidSliceU8_tail_admissible".into(),
            lean_statement: "axiom RustValidSliceU8_tail_admissible : True".into(),
            nl_statement: "\\begin{definition}tail admissibility\\end{definition}".into(),
            citation_locator: "rust-reference/src/types/slice.md".into(),
            rust_justification: "language guarantee".into(),
            needed_by: vec!["parse_number_faithful".into()],
            gate_from_invalid_attempt: false,
            claim_class: String::new(),
        });
        state.audit_plan = Some(AuditPlan {
            report: "need-input diagnosis".into(),
            need_input_audit: true,
            written_at_cycle: state.cycle,
            ..AuditPlan::default()
        });
        let request = issue_request_for_test(&mut state, RequestKind::StuckMathAudit);
        let response = StuckMathAuditResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Ok,
            assumptions_lane_verdict: "pass".into(),
            assumptions_lane_hunt_result: "failed to refute over 10k runs".into(),
            ..StuckMathAuditResponse::default()
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("lane pass under a need-input plan must not violate the latch invariant");
        assert!(outcome.state.audit_plan.is_none());
        assert!(outcome
            .state
            .superseded_audit_plan
            .as_ref()
            .is_some_and(|plan| plan.need_input_audit));
        assert!(!outcome.state.stuck_math_audit.active);
        let ev = outcome
            .state
            .latest_assumptions_lane_evidence
            .last()
            .expect("lane verdict recorded as reviewer evidence");
        assert_eq!(ev.verdict, "pass");
        assert_eq!(ev.axiom_name, "RustValidSliceU8_tail_admissible");
        outcome.state.validate().expect("post-lane state validates");
    }

    #[test]
    fn polarity_flip_with_live_consumer_is_bounced_naming_the_consumer() {
        // dec2flt cycle-275 regression: flipping a Decide pair demotes its
        // current side to Dormant/, so a live node importing it leaves the
        // tablet unbuildable and the supervisor dies before the flip
        // commits. The audit response must bounce, naming the consumer.
        let mut state = under_model_audit_state();
        state.stuck_math_audit.need_input_audit = None;
        // Mirror the live incident: TheoremStating, with the pair's node in
        // the active seat.
        state.phase = Phase::TheoremStating;
        state.target_edit_mode = TargetEditMode::Global;
        state.proof_edit_mode = ProofEditMode::Local;
        state.active_node = Some(NodeId::from("Correct"));
        let consumer = NodeId::from("nan_like_consumer");
        state.live.present_nodes.insert(consumer.clone());
        state
            .deps
            .insert(consumer.clone(), BTreeSet::from([NodeId::from("Correct")]));
        state.ensure_node_metadata();
        let request = issue_request_for_test(&mut state, RequestKind::StuckMathAudit);
        let response = StuckMathAuditResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Ok,
            report: "## Claim being audited\n".to_string()
                + &"x".repeat(AUDIT_REPORT_TEXT_MIN_CHARS),
            set_live_polarity: "disprove".into(),
            ..StuckMathAuditResponse::default()
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("guarded flip must retry, not error");
        let reason = &outcome.state.latest_stuck_math_audit_rejection_reason;
        assert!(
            reason.contains("nan_like_consumer") && reason.contains("still import it"),
            "flip with a live consumer must bounce naming it; got: {reason}"
        );
        assert!(outcome.state.pv_live_polarity.is_empty());
        assert!(
            !outcome
                .commands
                .iter()
                .any(|c| matches!(c, ProtocolCommand::FlipDormantDecideFiles { .. })),
            "no disk flip may be emitted for a bounced ruling"
        );
    }

    #[test]
    fn consumer_blocked_bug_deferral_with_tasks_is_accepted_not_bounced() {
        // A NeedInputAuditor that rules the target false but DEFERS the flip —
        // confirm_need_input=false plus recovery tasks that re-found the live
        // consumers off the target first — must be ACCEPTED, not bounced by the
        // consumer guard. The `bug`-synthesis does not force a flip on a deferral
        // (a Decide flip is autonomous; the guard here is only build-safety); the
        // flip lands in a later audit once no live node imports the target.
        let mut state = under_model_audit_state();
        state.stuck_math_audit.need_input_audit = None;
        state.phase = Phase::TheoremStating;
        state.target_edit_mode = TargetEditMode::Global;
        state.proof_edit_mode = ProofEditMode::Local;
        state.active_node = Some(NodeId::from("Correct"));
        let consumer = NodeId::from("nan_like_consumer");
        state.live.present_nodes.insert(consumer.clone());
        state
            .deps
            .insert(consumer.clone(), BTreeSet::from([NodeId::from("Correct")]));
        state.ensure_node_metadata();
        let request = issue_request_for_test(&mut state, RequestKind::StuckMathAudit);
        let response = StuckMathAuditResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Ok,
            report: "## Claim being audited\n".to_string()
                + &"x".repeat(AUDIT_REPORT_TEXT_MIN_CHARS),
            confirm_need_input: false,
            under_model_ruling: "bug".into(),
            set_live_polarity: String::new(),
            tasks: vec![AuditTask {
                id: "task-1".into(),
                title: "Re-found the consumer off the false target".into(),
                body: "Replace nan_like_consumer's use of Correct with a success-conditioned residue lemma, then send a worker.".into(),
                ..AuditTask::default()
            }],
            ..StuckMathAuditResponse::default()
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("a deferral-with-tasks must be accepted");
        assert!(
            !outcome
                .state
                .latest_stuck_math_audit_rejection_reason
                .contains("still import it"),
            "a deferral-with-tasks must not bounce on the consumer guard; got: {}",
            outcome.state.latest_stuck_math_audit_rejection_reason
        );
        // No flip is enacted — it is deferred to a later audit.
        assert!(outcome.state.pv_live_polarity.is_empty());
        assert!(!outcome
            .commands
            .iter()
            .any(|c| matches!(c, ProtocolCommand::FlipDormantDecideFiles { .. })));
    }

