    #[test]
    fn flip_prunes_demoted_side_local_closure_records() {
        // Record-prune: a stale closure record left on the demoted side
        // would resurrect the node as "closed" on flip-back without
        // re-verification. All three record surfaces must be pruned.
        let primary = trellis_kernel::ChallengeTargetId::from("goal:correct");
        let mut state = decide_pair_state();
        let node = NodeId::from("Correct");
        state
            .local_closure_records
            .insert(node.clone(), LocalClosureRecord::default());
        state
            .local_closure_failures
            .insert(node.clone(), ErrorSummary::default());
        state.local_closure_unverified_nodes.insert(node.clone());
        apply_decide_polarity_flip(&mut state, &primary, "disprove", false);
        assert!(!state.local_closure_records.contains_key(&node));
        assert!(!state.local_closure_failures.contains_key(&node));
        assert!(!state.local_closure_unverified_nodes.contains(&node));
    }

    #[test]
    fn stuck_math_audit_response_serde_back_compat_for_target_field() {
        // Absent on the wire → None; None → absent on the wire (existing
        // serialized responses stay byte-identical); Some round-trips.
        let response = StuckMathAuditResponse::default();
        let serialized = serde_json::to_value(&response).expect("serialize");
        assert!(
            serialized.get("set_live_polarity_target").is_none(),
            "None must not serialize (byte-compatible back-compat)"
        );
        let deserialized: StuckMathAuditResponse =
            serde_json::from_value(serialized).expect("deserialize");
        assert!(deserialized.set_live_polarity_target.is_none());

        let response = StuckMathAuditResponse {
            set_live_polarity_target: Some("goal:correct".into()),
            ..StuckMathAuditResponse::default()
        };
        let serialized = serde_json::to_value(&response).expect("serialize");
        assert_eq!(
            serialized.get("set_live_polarity_target"),
            Some(&serde_json::json!("goal:correct"))
        );
        let deserialized: StuckMathAuditResponse =
            serde_json::from_value(serialized).expect("deserialize");
        assert_eq!(
            deserialized.set_live_polarity_target.as_deref(),
            Some("goal:correct")
        );
    }

    #[test]
    fn reviewer_next_active_to_assumptions_is_rejected_in_every_mode() {
        // The exact worker-595 misroute (Continue + next_active=Assumptions +
        // next_mode=Restructure) and its Global-mode variant must both bounce
        // as illegal reviewer responses instead of dispatching a doomed
        // carrier-less worker.
        for mode in [TaskMode::Restructure, TaskMode::Global] {
            let mut state = approach_audit_state();
            state.stage = Stage::Reviewer;
            let assumptions = NodeId::from(trellis_kernel::assumptions_registry::ASSUMPTIONS_NODE);
            let request = issue_request_for_test(&mut state, RequestKind::Review);
            let outcome = apply_event(
                state,
                ProtocolEvent::WrapperResponse {
                    response: WrapperResponse::Review(ReviewResponse {
                        request_id: request.id,
                        cycle: request.cycle,
                        status: ResponseStatus::Ok,
                        decision: ReviewDecisionKind::Continue,
                        next_mode: mode,
                        next_active: Some(assumptions.clone()),
                        authorized_nodes: if mode == TaskMode::Restructure {
                            BTreeSet::from([assumptions.clone()])
                        } else {
                            BTreeSet::new()
                        },
                        ..ReviewResponse::default()
                    }),
                },
            )
            .expect("illegal routing must re-issue the review, not error");
            assert!(
                !outcome.state.latest_review_rejection_reasons.is_empty(),
                "routing next_active to Assumptions in {mode:?} must be rejected"
            );
            assert_eq!(
                first_issued_request(&outcome.commands).kind,
                RequestKind::Review,
                "a rejected review response re-issues the Review request"
            );
            assert!(outcome.state.assumption_authoring.is_none());
        }
    }

    #[test]
    fn reviewer_enact_without_recorded_candidate_is_rejected() {
        // The enact flag is legal only over an auditor-named candidate: with
        // none recorded, the response bounces with a named reason instead of
        // dispatching an unanchored authoring worker.
        let mut state = approach_audit_state();
        state.stage = Stage::Reviewer;
        assert!(state.pending_authoring_candidate.is_empty());
        let request = issue_request_for_test(&mut state, RequestKind::Review);
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Review(ReviewResponse {
                    request_id: request.id,
                    cycle: request.cycle,
                    status: ResponseStatus::Ok,
                    decision: ReviewDecisionKind::Continue,
                    next_mode: request.mode,
                    assumption_authoring_request: true,
                    ..ReviewResponse::default()
                }),
            },
        )
        .expect("illegal enact must re-issue the review, not error");
        assert!(outcome
            .state
            .latest_review_rejection_reasons
            .iter()
            .any(|reason| reason.contains("assumption_authoring_request")));
        assert_eq!(
            first_issued_request(&outcome.commands).kind,
            RequestKind::Review
        );
        assert!(outcome.state.assumption_authoring.is_none());
    }

    #[test]
    fn carrierless_worker_issue_on_assumptions_node_parks_to_human_gate() {
        // Engine backstop (phase-agnostic): a Worker request on the
        // under-model Assumptions node without the authoring carrier must
        // never be issued — the deterministic checker rejects every such
        // burst, so issuing one guarantees a doomed worker and (via its
        // system_feedback) a supervisor halt. This is exactly the persisted
        // shape of the live worker-595 state on resume.
        let mut state = approach_audit_state();
        let assumptions = NodeId::from(trellis_kernel::assumptions_registry::ASSUMPTIONS_NODE);
        state.stage = Stage::Worker;
        state.active_node = Some(assumptions.clone());
        assert!(state.assumption_authoring.is_none());
        let command = issue_request(&mut state, RequestKind::Worker);
        let ProtocolCommand::IssueRequest { request } = command else {
            panic!("expected an issued request");
        };
        assert_eq!(
            request.kind,
            RequestKind::HumanGate,
            "carrier-less Assumptions worker must park to the human gate"
        );
        assert_eq!(state.stage, Stage::HumanGate);
        assert_eq!(state.gate_kind, GateKind::NeedInput);
        assert!(state
            .latest_stuck_math_audit_rejection_reason
            .contains("assumption-authoring carrier"));

        // With the carrier live the same dispatch goes through untouched.
        let mut state = approach_audit_state();
        state.stage = Stage::Worker;
        state.active_node = Some(assumptions.clone());
        state.assumption_authoring = Some(AssumptionAuthoringContext {
            candidate_invariant: "narrow boundary contract".into(),
            needed_by: Vec::new(),
            gate_from_invalid_attempt: false,
        });
        state.pending_task = Some(PendingTask {
            node: Some(assumptions.clone()),
            mode: TaskMode::Restructure,
            authorized_nodes: BTreeSet::from([assumptions]),
            allow_new_obligations: false,
            must_close_active: false,
            next_worker_context_mode: WorkerContextMode::Fresh,
            ..PendingTask::default()
        });
        let command = issue_request(&mut state, RequestKind::Worker);
        let ProtocolCommand::IssueRequest { request } = command else {
            panic!("expected an issued request");
        };
        assert_eq!(request.kind, RequestKind::Worker);
        assert_eq!(state.stage, Stage::Worker);
    }

    #[test]
    fn assumption_authoring_scope_survives_missing_pending_task() {
        // Regression for restart/rewind recovery: assumption authoring must not
        // fall back to the generic theorem-restructure envelope when the
        // reviewer pending task is absent from persisted state.
        let mut state = under_model_audit_state();
        let assumptions = NodeId::from(trellis_kernel::assumptions_registry::ASSUMPTIONS_NODE);
        state.phase = Phase::TheoremStating;
        state.stage = Stage::Worker;
        state.active_node = Some(assumptions.clone());
        state.target_edit_mode = TargetEditMode::Restructure;
        state.proof_edit_mode = ProofEditMode::Local;
        state.pending_task = None;
        state.assumption_authoring = Some(AssumptionAuthoringContext {
            candidate_invariant: "every slice length is at most isize::MAX".into(),
            needed_by: vec!["goal:correct".into()],
            gate_from_invalid_attempt: false,
        });

        assert_eq!(
            state.current_worker_validation_kind(),
            WorkerValidationKind::TheoremRestructure
        );
        assert_eq!(
            state.current_worker_authorized_nodes(),
            BTreeSet::from([assumptions.clone()])
        );
        assert!(!state.current_worker_allow_new_obligations());

        let request = issue_request_for_test(&mut state, RequestKind::Worker);
        assert_eq!(
            request.worker_context.authorized_nodes,
            BTreeSet::from([assumptions.clone()])
        );
        assert!(!request.worker_context.allow_new_obligations);
        assert_eq!(
            request.worker_context.next_context_mode,
            WorkerContextMode::Fresh
        );
        assert_eq!(
            request.worker_acceptance.authorized_nodes,
            BTreeSet::from([assumptions.clone()])
        );
        assert_eq!(
            request.worker_acceptance.validation_execution_plan,
            vec![
                WorkerValidationExecutionPlanStep::TheoremTargetEditScope {
                    target: Some(assumptions.clone()),
                    initial_scope: BTreeSet::from([assumptions.clone()]),
                },
                WorkerValidationExecutionPlanStep::ScopedTablet {
                    allowed_nodes_mode: ScopedTabletAllowedNodesMode::PreviousOrExplicit,
                    explicit_nodes: BTreeSet::from([assumptions]),
                },
            ]
        );
        assert!(request.assumption_authoring.is_some());
    }

    #[test]
    fn assumption_authoring_worker_stages_c_then_corr_pass_dispatches_assumptions_lane() {
        // PV under-model (Slice 2): an authoring worker burst (assumption_authoring
        // live) stages `C` in `Assumptions`; ordinary NodeCorr must pass before
        // the DISTINCT assumptions lane runs.
        let mut state = decide_pair_state();
        seed_assumptions_node_for_test(&mut state);
        let assumptions = NodeId::from(trellis_kernel::assumptions_registry::ASSUMPTIONS_NODE);
        state.phase = Phase::ProofFormalization;
        state.stage = Stage::Worker;
        state.cycle = 11;
        state.active_node = Some(assumptions.clone());
        state.pending_task = Some(PendingTask {
            node: Some(assumptions.clone()),
            mode: TaskMode::Restructure,
            authorized_nodes: BTreeSet::from([assumptions.clone()]),
            allow_new_obligations: false,
            must_close_active: false,
            next_worker_context_mode: WorkerContextMode::Fresh,
            ..PendingTask::default()
        });
        state.ensure_node_metadata();
        state.assumption_authoring = Some(AssumptionAuthoringContext {
            candidate_invariant: "every slice length is ≤ isize::MAX".into(),
            needed_by: vec!["goal:correct".into()],
            gate_from_invalid_attempt: false,
        });
        let request = issue_request_for_test(&mut state, RequestKind::Worker);
        let mut snapshot = state.live.clone();
        snapshot
            .corr_current_fingerprints
            .insert(assumptions.clone(), "assumptions-fp-1".into());
        let response = WorkerResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Ok,
            outcome: WorkerOutcome::Valid,
            snapshot,
            authored_assumption_id: "slice_len_le_isize_max".into(),
            authored_axiom_name: "dec2flt.slice_len_le_isize_max".into(),
            staged_assumption_lean_statement: "axiom dec2flt.slice_len_le_isize_max : True"
                .into(),
            staged_assumption_nl_statement:
                "\\begin{definition}Every slice allocation length is at most isize::MAX.\\end{definition}"
                    .into(),
            authored_citation_locator: "Rust Reference: allocation size <= isize::MAX".into(),
            authored_rust_justification: "the allocator never produces a larger allocation".into(),
            ..WorkerResponse::default()
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(response),
            },
        )
        .expect("authoring worker response must route through corr");
        assert_eq!(outcome.state.stage, Stage::VerifyCorr);
        assert!(outcome.state.assumption_authoring.is_some());
        assert!(outcome.state.pending_assumption_draft.is_some());
        let corr_request = match outcome.commands.as_slice() {
            [ProtocolCommand::IssueRequest { request }] => request.clone(),
            other => panic!("expected corr request, got {:?}", other),
        };
        assert_eq!(corr_request.kind, RequestKind::Corr);
        assert!(corr_request.corr_verify_nodes.contains(&assumptions));
        let corr_authoring = corr_request
            .assumption_authoring
            .as_ref()
            .expect("under-model Assumptions Corr request must carry authoring context");
        assert_eq!(
            corr_authoring.candidate_invariant,
            "every slice length is ≤ isize::MAX"
        );
        assert_eq!(corr_authoring.needed_by, vec!["goal:correct"]);
        let corr_draft = corr_request
            .pending_assumption_draft
            .as_ref()
            .expect("under-model Assumptions Corr request must carry the pending draft");
        assert_eq!(corr_draft.lane.assumption_id, "slice_len_le_isize_max");
        assert_eq!(
            corr_draft.lane.lean_statement,
            "axiom dec2flt.slice_len_le_isize_max : True"
        );
        assert!(corr_draft
            .lane
            .nl_statement
            .contains("Every slice allocation length"));

        let pass_updates: CorrNodeLaneUpdates = corr_request
            .verify_lanes
            .iter()
            .map(|lane| {
                (
                    lane.clone(),
                    BTreeMap::from([(assumptions.clone(), Update::Set(CorrStatus::Pass))]),
                )
            })
            .collect();
        let outcome = apply_event(
            outcome.state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Corr(CorrResponse {
                    request_id: corr_request.id,
                    cycle: corr_request.cycle,
                    status: ResponseStatus::Ok,
                    node_lane_updates: pass_updates,
                    target_lane_updates: empty_corr_target_lanes(&corr_request.verify_lanes),
                    reviewer_evidence: BTreeMap::new(),
                    rust_witness_artifact_correspondence: None,
                    conditional_theorem_correspondence: None,
                }),
            },
        )
        .expect("Assumptions Corr pass must dispatch the assumptions lane");
        assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
        assert!(outcome.state.assumption_authoring.is_none());
        assert!(outcome.state.pending_assumption_draft.is_none());
        let lane = outcome
            .state
            .stuck_math_audit
            .assumptions_lane
            .as_ref()
            .expect("assumptions lane carrier must be set");
        assert_eq!(lane.assumption_id, "slice_len_le_isize_max");
        assert_eq!(lane.axiom_name, "dec2flt.slice_len_le_isize_max");
        assert_eq!(
            lane.lean_statement,
            "axiom dec2flt.slice_len_le_isize_max : True"
        );
        assert!(lane.nl_statement.contains("Every slice allocation length"));
    }

    #[test]
    fn assumptions_lane_pass_records_pending_and_bumps_count() {
        // PV under-model (Slice 2): an assumptions-lane PASS records the
        // assumption pending (RecordProposedAssumption command + the in-state
        // count bump) and routes back to the reviewer — the target parks.
        let mut state = decide_pair_state();
        state.phase = Phase::ProofFormalization;
        state.stage = Stage::StuckMathAudit;
        state.cycle = 13;
        state.active_node = None;
        state.ensure_node_metadata();
        state.stuck_math_audit.active = true;
        state.stuck_math_audit.assumptions_lane = Some(AssumptionsLaneContext {
            assumption_id: "slice_len_le_isize_max".into(),
            candidate_invariant: "every slice length is ≤ isize::MAX".into(),
            axiom_name: "dec2flt.slice_len_le_isize_max".into(),
            lean_statement: "axiom dec2flt.slice_len_le_isize_max : True".into(),
            nl_statement:
                "\\begin{definition}Every slice allocation length is at most isize::MAX.\\end{definition}"
                    .into(),
            citation_locator: "Rust Reference: alloc <= isize::MAX".into(),
            rust_justification: "the allocator never produces a larger allocation".into(),
            needed_by: vec!["goal:correct".into()],
            gate_from_invalid_attempt: false,
            claim_class: String::new(),
        });
        let request = issue_request_for_test(&mut state, RequestKind::StuckMathAudit);
        let response = StuckMathAuditResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Ok,
            assumptions_lane_verdict: "pass".into(),
            assumptions_lane_hunt_result: "failed to refute over 10k runs".into(),
            ..StuckMathAuditResponse::default()
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("assumptions-lane pass must record pending and route to reviewer");
        assert_eq!(outcome.state.pending_under_model_assumptions, 1);
        assert!(!outcome.state.stuck_math_audit.active);
        assert!(outcome.state.stuck_math_audit.assumptions_lane.is_none());
        let review_request = first_issued_request(&outcome.commands);
        assert_eq!(review_request.kind, RequestKind::Review);
        assert!(
            !review_request.stuck_math_audit.active,
            "post-assumptions-lane Review must not inherit generic StuckMathAudit mode"
        );
        assert!(review_request.stuck_math_audit.assumptions_lane.is_none());
        assert!(outcome.commands.iter().any(|c| matches!(
            c,
            ProtocolCommand::RecordProposedAssumption { record }
                if record.id == "slice_len_le_isize_max"
                    && record.axiom_name == "dec2flt.slice_len_le_isize_max"
        )));
    }

    #[test]
    fn assumptions_lane_reject_routes_back_no_count_bump() {
        // PV under-model (Slice 2): an assumptions-lane REJECT (e.g. an
        // ineligible `unsafe`-precondition candidate) records nothing and routes
        // back to ordinary proving — the count stays 0.
        let mut state = decide_pair_state();
        state.phase = Phase::ProofFormalization;
        state.stage = Stage::StuckMathAudit;
        state.cycle = 13;
        state.active_node = None;
        state.ensure_node_metadata();
        state.stuck_math_audit.active = true;
        state.stuck_math_audit.assumptions_lane = Some(AssumptionsLaneContext {
            assumption_id: "vec_cap_invariant".into(),
            candidate_invariant: "the caller upholds the Vec capacity invariant".into(),
            axiom_name: "crate.vec_cap_invariant".into(),
            lean_statement: "axiom crate.vec_cap_invariant : True".into(),
            nl_statement:
                "\\begin{definition}The caller upholds the Vec capacity invariant.\\end{definition}"
                    .into(),
            citation_locator: "(none — this is a program-maintained invariant)".into(),
            rust_justification: "the program maintains it".into(),
            needed_by: vec!["goal:correct".into()],
            gate_from_invalid_attempt: false,
            claim_class: String::new(),
        });
        let request = issue_request_for_test(&mut state, RequestKind::StuckMathAudit);
        let response = StuckMathAuditResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Ok,
            assumptions_lane_verdict: "reject".into(),
            assumptions_lane_reason: "INELIGIBLE: program-maintained invariant, not a language \
                                      guarantee — route to ordinary proving"
                .into(),
            ..StuckMathAuditResponse::default()
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("assumptions-lane reject must route back to reviewer");
        assert_eq!(outcome.state.pending_under_model_assumptions, 0);
        assert!(!outcome.state.stuck_math_audit.active);
        assert!(outcome.state.stuck_math_audit.assumptions_lane.is_none());
        assert_eq!(outcome.state.stage, Stage::Reviewer);
        let review_request = first_issued_request(&outcome.commands);
        assert_eq!(review_request.kind, RequestKind::Review);
        assert!(
            !review_request.stuck_math_audit.active,
            "post-assumptions-lane Review must not inherit generic StuckMathAudit mode"
        );
        assert!(review_request.stuck_math_audit.assumptions_lane.is_none());
        assert!(!outcome
            .commands
            .iter()
            .any(|c| matches!(c, ProtocolCommand::RecordProposedAssumption { .. })));
        assert!(outcome.commands.iter().any(|c| matches!(
            c,
            ProtocolCommand::RejectStagedAssumption { assumption_id, .. }
                if assumption_id == "vec_cap_invariant"
        )));
    }

    #[test]
    fn legacy_assumption_review_approve_projects_then_presents_meaning_gate() {
        // Part G: approving the legacy AssumptionReview batch emits the
        // projection, clears the count, and returns to the distinct prose
        // Advance meaning gate. It does not advance the phase.
        let mut state = decide_pair_state();
        state.phase = Phase::TheoremStating;
        state.stage = Stage::HumanGate;
        state.gate_kind = GateKind::AssumptionReview;
        state.pending_under_model_assumptions = 2;
        state.cycle = 21;
        let request = issue_request_for_test(&mut state, RequestKind::HumanGate);
        let response = HumanGateResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Ok,
            choice: HumanChoice::Approve,
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::HumanGate(response),
            },
        )
        .expect("AssumptionReview approve must project + present meaning");
        assert_eq!(outcome.state.phase, Phase::TheoremStating);
        assert_eq!(outcome.state.stage, Stage::HumanGate);
        assert_eq!(outcome.state.gate_kind, GateKind::Advance);
        assert_eq!(outcome.state.pending_under_model_assumptions, 0);
        assert!(outcome
            .commands
            .iter()
            .any(|c| matches!(c, ProtocolCommand::ProjectAllPendingAssumptions)));
        assert!(outcome.commands.iter().any(|c| matches!(
            c,
            ProtocolCommand::RenderTrustAdvanceGatePresentation
        )));
        assert_eq!(
            first_issued_request(&outcome.commands).kind,
            RequestKind::HumanGate
        );
    }

    #[test]
    fn required_v1_advance_approval_projects_pending_batch_atomically() {
        let mut state = decide_pair_state();
        install_minimal_required_v1_trust(&mut state);
        state.phase = Phase::TheoremStating;
        state.stage = Stage::HumanGate;
        state.gate_kind = GateKind::Advance;
        state.trust_base.routine_gate_state = TrustRoutineGateState::NotPresented;
        state.trust_base.current_human_approval_event_hash = None;
        state.pending_under_model_assumptions = 2;
        state.cycle = 21;
        let request = issue_request_for_test(&mut state, RequestKind::HumanGate);
        let response = HumanGateResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Ok,
            choice: HumanChoice::Approve,
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::HumanGate(response),
            },
        )
        .expect("the sole required-v1 approval projects assumptions and meaning together");

        assert_eq!(outcome.state.phase, Phase::ProofFormalization);
        assert_eq!(outcome.state.pending_under_model_assumptions, 0);
        assert_eq!(
            outcome.state.trust_base.routine_gate_state,
            TrustRoutineGateState::ApprovalCommitPending
        );
        let trust_index = outcome
            .commands
            .iter()
            .position(|command| {
                matches!(command, ProtocolCommand::CommitTrustGateDecision { .. })
            })
            .expect("required-v1 approval record");
        let project_index = outcome
            .commands
            .iter()
            .position(|command| matches!(command, ProtocolCommand::ProjectAllPendingAssumptions))
            .expect("pending batch projection");
        assert!(
            trust_index < project_index,
            "the decision first binds the still-pending batch presentation"
        );
        assert!(!outcome.commands.iter().any(|command| matches!(
            command,
            ProtocolCommand::RenderAssumptionsReview
        )));
    }

