    #[test]
    fn initial_planner_retry_keeps_carrier_and_redispatches_after_exhaustion() {
        // G4 retry parity with the revision planner: a malformed planner burst
        // retries; exhaustion falls through to the reviewer WITHOUT taking the
        // carrier; the next StartCycle re-dispatches the planner.
        let state = initial_planning_state_for_test();
        let outcome = apply_event(state, ProtocolEvent::StartCycle).expect("dispatch planner");
        let request = first_issued_request(&outcome.commands).clone();
        let malformed = StuckMathAuditResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Malformed,
            ..StuckMathAuditResponse::default()
        };
        // First malformed: within the retry budget — the planner re-issues.
        let outcome = apply_event(
            outcome.state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(malformed.clone()),
            },
        )
        .expect("malformed planner burst retries");
        assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
        assert!(outcome.state.stuck_math_audit.initial_planning.is_some());
        let retry_request = first_issued_request(&outcome.commands).clone();
        assert_eq!(retry_request.kind, RequestKind::StuckMathAudit);
        // Second malformed: budget exhausted — falls through to the reviewer,
        // carrier intact.
        let malformed_again = StuckMathAuditResponse {
            request_id: retry_request.id,
            cycle: retry_request.cycle,
            ..malformed
        };
        let outcome = apply_event(
            outcome.state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(malformed_again),
            },
        )
        .expect("exhausted planner burst routes to reviewer");
        assert_eq!(outcome.state.stage, Stage::Reviewer);
        assert!(
            outcome.state.stuck_math_audit.initial_planning.is_some(),
            "retry exhaustion must not take the carrier (revision parity)"
        );
    }

    #[test]
    fn accepted_initial_planner_writes_advisory_plan_and_routes_to_review() {
        let mut state = initial_planning_state_for_test();
        state.cycle = 1;
        state.stage = Stage::StuckMathAudit;
        let request = issue_request_for_test(&mut state, RequestKind::StuckMathAudit);
        let mut response = initial_planner_response_for_test();
        response.request_id = request.id;
        response.cycle = request.cycle;
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("accepted initial-planning response");
        assert_eq!(
            outcome.state.latest_stuck_math_audit_rejection_reason, "",
            "must not have been rejected"
        );
        let plan = outcome.state.audit_plan.as_ref().expect("audit plan");
        assert!(plan.initial_plan);
        assert!(!plan.revision_audit);
        assert!(!plan.need_input_audit);
        assert_eq!(plan.tasks.len(), 1);
        // Carrier cleared; retry bookkeeping reset; reviewer routes next.
        assert!(outcome.state.stuck_math_audit.initial_planning.is_none());
        assert_eq!(outcome.state.stuck_math_audit_burst_retry_count, 0);
        assert_eq!(outcome.state.stage, Stage::Reviewer);
        // The latch stays ACTIVE: dismiss_audit_plan legality (the plan's
        // retirement path) requires it, and the view pin keeps the plan
        // visible to Review/Worker.
        assert!(outcome.state.stuck_math_audit.active);
        match outcome.commands.as_slice() {
            [ProtocolCommand::IssueRequest { request }] => {
                assert_eq!(request.kind, RequestKind::Review);
                assert!(
                    request
                        .audit_plan
                        .as_ref()
                        .is_some_and(|plan| plan.initial_plan),
                    "the routing Review must carry the initial plan"
                );
            }
            other => panic!("expected Review request, got {other:?}"),
        }
    }

    #[test]
    fn pv_initial_plan_candidate_reaches_the_enactable_review_contract() {
        // Non-trust PV (spec mode): the assumption lane is live and the
        // audit→reviewer→authoring path is the sanctioned route. The
        // fresh-run planner is a distinct early-return lane, but its
        // accepted plan is still a PLAN-writing audit: a structured
        // candidate C must take the same reviewer-enact path as an
        // ordinary approach audit.
        let mut state = initial_planning_state_for_test();
        state.pv_tablet_configured = true;
        seed_assumptions_node_for_test(&mut state);
        state.ensure_node_metadata();
        state.cycle = 1;
        state.stage = Stage::StuckMathAudit;
        let request = issue_request_for_test(&mut state, RequestKind::StuckMathAudit);
        let candidate = "axiom all_slices_rust_valid_u8 : ∀ (s : Slice Std.U8), RustValidSliceU8 s";
        let mut response = initial_planner_response_for_test();
        response.request_id = request.id;
        response.cycle = request.cycle;
        response.under_model_candidate_invariant = candidate.into();

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("accepted PV initial-planning response");

        assert_eq!(outcome.state.pending_authoring_candidate, candidate);
        assert!(outcome.state.audit_plan.is_some(), "accepted initial plan");
        let review_request = first_issued_request(&outcome.commands);
        assert_eq!(review_request.kind, RequestKind::Review);
        assert_eq!(review_request.pending_authoring_candidate, candidate);
        assert_eq!(
            review_request.review_contract["assumption_authoring_contract"]["candidate_invariant"],
            serde_json::json!(candidate)
        );
        assert!(
            review_request.review_contract["artifact_contract"]["optional_fields"]
                .as_array()
                .expect("review optional_fields")
                .iter()
                .any(|field| field == "assumption_authoring_request")
        );
    }

    #[test]
    fn initial_planner_memory_operations_accepted_node_retirement_rejected() {
        // The planner lane WRITES process memory (its prompt instructs
        // recording refuted routes; consumption is lane-agnostic and runs
        // before lane routing) — the historical rejection was the exact
        // mechanism by which a coverage audit's refuted-route findings
        // decayed to prose. Node retirement stays structural-only.
        let mut state = initial_planning_state_for_test();
        state.cycle = 1;
        state.stage = Stage::StuckMathAudit;
        state.process_memory_seq = 7;
        let request = issue_request_for_test(&mut state, RequestKind::StuckMathAudit);
        let mut with_memory = initial_planner_response_for_test();
        with_memory.request_id = request.id;
        with_memory.cycle = request.cycle;
        with_memory.memory_operations = vec![crate::process_memory::MemoryOperation {
            op: "add".into(),
            entry_type: "refuted-route".into(),
            coarse_node: "global".into(),
            title: "t".into(),
            body: "b".into(),
            ..Default::default()
        }];
        assert_eq!(
            stuck_math_audit_validation_failure(&state, &with_memory),
            None,
            "memory_operations are legal on the initial-planning lane"
        );
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(with_memory),
            },
        )
        .expect("accepted planner response with memory operations");
        assert_eq!(
            outcome.state.latest_stuck_math_audit_rejection_reason, "",
            "must not have been rejected"
        );
        assert!(
            outcome
                .state
                .audit_plan
                .as_ref()
                .is_some_and(|plan| plan.initial_plan),
            "the advisory plan is still written"
        );
        assert_eq!(
            outcome.state.process_memory_seq, 8,
            "the add consumed a kernel id"
        );
        assert!(
            outcome
                .commands
                .iter()
                .any(|c| matches!(c, ProtocolCommand::ApplyProcessMemoryOperations { .. })),
            "the file-materialization command rides the acceptance: {:?}",
            outcome.commands
        );

        let state = initial_planning_state_for_test();
        let mut with_retirement = initial_planner_response_for_test();
        with_retirement.node_retirement_request = Some(crate::model::NodeRetirementRequest {
            nodes: BTreeSet::from([NodeId::from("a")]),
            reason: "stale".into(),
            ..Default::default()
        });
        let reason = stuck_math_audit_validation_failure(&state, &with_retirement)
            .expect("node_retirement_request must be rejected on the initial-planning lane");
        assert!(reason.contains("node_retirement_request"), "{reason}");
    }

