    #[test]
    fn theorem_stating_with_live_initial_plan_dispatches_worker_not_audit() {
        // Suppression: while the accepted initial plan is live the audit must
        // not re-dispatch on the re-audit interval — workers execute the plan
        // (mirror of revision_stating_with_accepted_plan_dispatches_worker_
        // not_audit).
        let mut state = base_state();
        state.stage = Stage::Start;
        state.cycle = 6;
        state.active_node = Some("a".into());
        let mut plan = make_test_audit_plan();
        plan.initial_plan = true;
        state.audit_plan = Some(plan);
        let interval = stuck_math_audit_reaudit_interval_cycles();
        state.activate_stuck_math_audit_latch("initial planner (test)".to_string());
        state.last_stuck_math_audit_dispatched_cycle = Some(6u32.saturating_sub(interval));
        let outcome = apply_event(state, ProtocolEvent::StartCycle).unwrap();
        assert_eq!(
            outcome.state.stage,
            Stage::Worker,
            "a live initial plan hands off to a Worker, never a re-audit"
        );
    }

    #[test]
    fn initial_plan_suppresses_dispatch_until_dismissed_then_triggers_revive() {
        // (b) suppression holds while the initial_plan is live; (a) after the
        // reviewer's dismiss_audit_plan retirement (plan -> superseded, latch
        // cleared) the ordinary stagnation triggers revive.
        let interval = stuck_math_audit_reaudit_interval_cycles();
        let mut plan = make_test_audit_plan();
        plan.initial_plan = true;
        let mut s = audit_dispatch_state(Some(plan), 10, 10 + interval);
        assert!(
            !should_dispatch_stuck_math_audit(&mut s),
            "a live initial plan suppresses the audit even past the re-audit interval"
        );
        // Reviewer retirement (what apply_review_audit_plan_actions does on
        // dismiss_audit_plan=true): plan to superseded, latch cleared.
        s.superseded_audit_plan = s.audit_plan.take();
        s.stuck_math_audit.active = false;
        s.stuck_math_audit.trigger.clear();
        s.stuck_math_audit.trigger_blockers.clear();
        s.stuck_math_audit.active_since_cycle = 0;
        assert!(
            should_dispatch_stuck_math_audit(&mut s),
            "the stagnation trigger must revive once the initial plan is retired"
        );
    }

    #[test]
    fn reviewer_dismisses_initial_plan_in_theorem_stating() {
        // The retirement path: a TheoremStating reviewer Continue with
        // dismiss_audit_plan=true against a live initial_plan is legal,
        // supersedes the plan, and clears the latch.
        let mut state = base_state();
        state.stage = Stage::Reviewer;
        state.cycle = 6;
        state.active_node = Some("a".into());
        // Keep an open PaperFaithfulness blocker (target "t" not yet Pass), as
        // a genuinely fresh post-plan run has: without a live blocker the
        // latch-refresh empty-blockers zeroing on the next dispatch would take
        // `audit_plan` a second time and clobber the `superseded_audit_plan`
        // snapshot the dismissal just wrote.
        state.paper_status.remove("t");
        state.paper_approved_fingerprints.remove("t");
        let mut plan = make_test_audit_plan();
        plan.initial_plan = true;
        state.audit_plan = Some(plan);
        state.activate_stuck_math_audit_latch("initial planner (test)".to_string());
        let request = issue_request_for_test(&mut state, RequestKind::Review);
        assert!(
            request
                .audit_plan
                .as_ref()
                .is_some_and(|plan| plan.initial_plan),
            "the Review request must surface the live initial plan"
        );
        let (paper_focus_ranges, paper_grounding) = test_paper_grounding();
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Review(ReviewResponse {
                    request_id: request.id,
                    cycle: request.cycle,
                    status: ResponseStatus::Ok,
                    decision: ReviewDecisionKind::Continue,
                    next_mode: TaskMode::Global,
                    dismiss_audit_plan: true,
                    // An active latch requires the reviewer to carry an audit
                    // report on a reset=none Continue.
                    stuck_math_audit: Some(StuckMathAuditReviewReport {
                        notes: "initial plan reviewed; dispatching workers to build the DAG".into(),
                        ..StuckMathAuditReviewReport::default()
                    }),
                    paper_focus_ranges,
                    paper_grounding,
                    ..ReviewResponse::default()
                }),
            },
        )
        .expect("dismissing the initial plan on a TheoremStating Continue is legal");
        assert!(
            outcome.state.audit_plan.is_none(),
            "dismissal retires the plan"
        );
        assert!(
            outcome
                .state
                .superseded_audit_plan
                .as_ref()
                .is_some_and(|plan| plan.initial_plan),
            "the retired plan is kept as advisory history"
        );
        assert!(
            !outcome.state.stuck_math_audit.active,
            "whole-plan dismissal clears the latch so triggers re-evaluate from scratch"
        );
    }

    // ===== Coverage re-planning (periodic coverage planner) =====

    /// TheoremStating state mid-construction with the coverage feature
    /// armed: target "t" covered by "a" (Pass everywhere, from
    /// `base_state`), target "u" configured with EMPTY coverage — a
    /// definite PaperFaithfulness Fail (`current_paper_state` on empty
    /// coverage), so the paper frontier stays empty and the would-be
    /// dispatch is Worker — no audit lane in flight, and
    /// `coverage_replanning_source` set. `StartCycle` bumps the cursor, so
    /// the trigger is evaluated at `cycle + 1`.
    fn coverage_replanning_state_for_test(
        last_dispatched: Option<u32>,
        cycle: u32,
    ) -> ProtocolState {
        let mut state = base_state();
        state.stage = Stage::Start;
        state.cycle = cycle;
        state.active_node = Some("a".into());
        state.configured_targets.insert("u".into());
        state.live.coverage.insert("u".into(), BTreeSet::new());
        state
            .live
            .paper_current_fingerprints
            .insert("u".into(), "paper-u".into());
        state.committed.coverage.insert("u".into(), BTreeSet::new());
        state
            .committed
            .paper_current_fingerprints
            .insert("u".into(), "paper-u".into());
        state.last_stuck_math_audit_dispatched_cycle = last_dispatched;
        state.coverage_replanning_source =
            Some(crate::model::InitialPlanningSource::PaperManuscript {
                paper_tex_path: "paper/main.tex".into(),
            });
        state
    }

    fn expected_coverage_trigger_string() -> String {
        "coverage re-planning: 1 configured target(s) with no covering node and 0 covered without a real (non-SKETCH) NL proof — assess the current plan and re-plan the route to full coverage".to_string()
    }

    /// Coverage-cadence honesty (dec2flt, 61 bursts of "0 configured
    /// target(s) still uncovered"): on a mode-B run with ZERO paper targets
    /// the cadence is held open by challenge Theorem targets whose covering
    /// nodes carry only SKETCH proofs, and the trigger string + coverage
    /// packet must say so — never "0 uncovered" with null packet fields.
    #[test]
    fn coverage_trigger_and_packet_count_sketch_only_challenge_targets() {
        let mut state = decide_pair_state();
        // Every paper target is fully covered by the real-proof node, so
        // ONLY the challenge side can hold the window open (the campaign
        // regime: "0 configured target(s) still uncovered", 61 bursts).
        state.live.present_nodes.insert(NodeId::from("PaperLemma"));
        state.proof_nodes.insert(NodeId::from("PaperLemma"));
        for target in state.configured_targets.clone() {
            state
                .live
                .coverage
                .insert(target, BTreeSet::from([NodeId::from("PaperLemma")]));
        }
        // The Decide pair's live-side covering node is SKETCH-only: the
        // pair (and only the pair — never its dormant refutation twin)
        // holds the window open.
        state
            .live
            .sketch_proof_nodes
            .insert(NodeId::from("Correct"));
        assert!(
            state.orphan_construction_window_open(&state.live),
            "sketch-only challenge coverage holds the window open"
        );
        let outstanding = state.coverage_outstanding_targets(&state.live);
        assert_eq!(
            outstanding,
            BTreeSet::from(["goal:correct".to_string()]),
            "the outstanding set rides the Decide primary, never the dormant twin"
        );
        let trigger = state.coverage_replanning_trigger_string();
        assert!(
            trigger.contains("1 covered without a real (non-SKETCH) NL proof"),
            "the trigger must count the targets actually holding the window open: {trigger}"
        );
        let covered = state.coverage_covered_targets(&state.live);
        assert!(
            covered.contains_key("goal:correct"),
            "the packet's covered map spans challenge targets: {covered:?}"
        );
        // The same fact, twice: once every covering proof is real, the
        // window closes and the cadence disarms — the dormant refutation
        // twin must not hold it open forever.
        state.live.sketch_proof_nodes.clear();
        assert!(
            state.coverage_outstanding_targets(&state.live).is_empty(),
            "a fully real-proved run has nothing outstanding"
        );
        assert!(
            !state.orphan_construction_window_open(&state.live),
            "window closed — the coverage cadence disarms with it"
        );
    }

    /// A1 regression pin: the arming decision is computed alongside
    /// `theorem_stating_audit_preempt`, BEFORE the preempt block stamps
    /// `last_stuck_math_audit_dispatched_cycle`. The trigger embeds the
    /// K-cooldown against that field, so a post-stamp evaluation would read
    /// `cycle - cycle = 0 < COVERAGE_REPLAN_INTERVAL_CYCLES` and this
    /// dispatch would go out as an ordinary structural audit with NO
    /// coverage carrier — which is exactly what this test would catch.
    #[test]
    fn coverage_planner_arming_decision_is_pre_stamp() {
        // post-StartCycle cycle = 5; last = 1 ⇒ elapsed 4 >= K ⇒ due. The
        // ONLY firing trigger is the coverage trigger (base_state has no
        // stagnation), the latch starts inactive, and no plan is live.
        let state = coverage_replanning_state_for_test(Some(1), 4);
        assert!(!state.stuck_math_audit.active);
        let outcome = apply_event(state, ProtocolEvent::StartCycle)
            .expect("coverage-due StartCycle dispatches the coverage planner");
        assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
        let request = first_issued_request(&outcome.commands);
        assert_eq!(request.kind, RequestKind::StuckMathAudit);
        // The stamp happened (top of the preempt block)...
        assert_eq!(
            outcome.state.last_stuck_math_audit_dispatched_cycle,
            Some(5)
        );
        // ...and the carrier was still armed from the PRE-stamp decision.
        let carrier = outcome
            .state
            .stuck_math_audit
            .initial_planning
            .as_ref()
            .expect("the coverage carrier must be armed");
        assert!(carrier.coverage_replanning);
        assert_eq!(
            carrier.uncovered_target_ids,
            BTreeSet::from(["u".to_string()])
        );
        assert_eq!(
            carrier.covered_targets,
            BTreeMap::from([("t".to_string(), BTreeSet::from(["a".to_string()]))])
        );
        assert!(matches!(
            carrier.source,
            crate::model::InitialPlanningSource::PaperManuscript { .. }
        ));
        assert_eq!(
            outcome.state.stuck_math_audit.trigger,
            expected_coverage_trigger_string()
        );
        // The request view carries the packet into the planner contract.
        assert!(request
            .stuck_math_audit
            .initial_planning
            .as_ref()
            .is_some_and(|ctx| ctx.coverage_replanning));
    }

    #[test]
    fn coverage_planner_fires_over_live_initial_plan_and_supersedes_it() {
        // A live planner plan does NOT block the cadence: the suppression
        // branch returns the coverage trigger, and the accepted re-plan
        // moves the live plan — dismissal state intact — into
        // `superseded_audit_plan` (the existing
        // `apply_initial_planning_response` snapshot).
        let mut state = coverage_replanning_state_for_test(Some(1), 4);
        let mut plan = make_test_audit_plan();
        plan.initial_plan = true;
        plan.tasks = vec![crate::model::AuditTask {
            id: "old-1".into(),
            title: "old task".into(),
            body: "already handled".into(),
            dismissed: true,
            dismissed_reason: "done".into(),
            dismissed_at_cycle: Some(3),
        }];
        state.audit_plan = Some(plan.clone());
        state.activate_stuck_math_audit_latch("initial planner (test)".to_string());
        let outcome = apply_event(state, ProtocolEvent::StartCycle)
            .expect("coverage cadence pierces the planner-plan suppression");
        assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
        let request = first_issued_request(&outcome.commands).clone();
        assert!(outcome
            .state
            .stuck_math_audit
            .initial_planning
            .as_ref()
            .is_some_and(|ctx| ctx.coverage_replanning));
        // Acceptance: the new plan replaces the live one; the old plan (with
        // its dismissed task) survives as the superseded snapshot.
        let mut response = initial_planner_response_for_test();
        response.request_id = request.id;
        response.cycle = request.cycle;
        let outcome = apply_event(
            outcome.state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("accepted coverage re-plan");
        assert_eq!(
            outcome.state.superseded_audit_plan,
            Some(plan),
            "the superseded snapshot must keep the old plan's dismissal state"
        );
        let new_plan = outcome.state.audit_plan.as_ref().expect("new plan");
        assert!(new_plan.initial_plan);
        assert_eq!(new_plan.tasks.len(), 1);
        assert!(!new_plan.tasks[0].dismissed);
        assert!(
            outcome.state.stuck_math_audit.initial_planning.is_none(),
            "acceptance clears the carrier"
        );
        assert_eq!(outcome.state.stage, Stage::Reviewer);
    }

    #[test]
    fn coverage_planner_malformed_retry_rederives_same_planner_request() {
        // O2(a): the carrier is IN STATE, so a transport-failed coverage
        // burst re-derives the same planner request on retry — same lane
        // view, same coverage packet — rather than degrading to an ordinary
        // audit.
        let state = coverage_replanning_state_for_test(Some(1), 4);
        let outcome = apply_event(state, ProtocolEvent::StartCycle).expect("dispatch");
        let request = first_issued_request(&outcome.commands).clone();
        assert!(request
            .stuck_math_audit
            .initial_planning
            .as_ref()
            .is_some_and(|ctx| ctx.coverage_replanning));
        let malformed = StuckMathAuditResponse {
            request_id: request.id,
            cycle: request.cycle,
            status: ResponseStatus::Malformed,
            ..StuckMathAuditResponse::default()
        };
        let outcome = apply_event(
            outcome.state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(malformed),
            },
        )
        .expect("malformed coverage burst retries");
        assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
        let retry_request = first_issued_request(&outcome.commands);
        assert_eq!(retry_request.kind, RequestKind::StuckMathAudit);
        assert_eq!(
            retry_request.stuck_math_audit, request.stuck_math_audit,
            "the retry must re-derive the SAME coverage-planner lane view from the in-state carrier"
        );
    }

    #[test]
    fn coverage_cadence_two_iterations_supersede_with_dismissal_trail() {
        // O2(b): two coverage dispatches K apart; each accepted plan
        // supersedes the prior with its dismissal trail preserved, and the
        // cooldown is re-stamped each generation.
        let state = coverage_replanning_state_for_test(Some(1), 4);
        let outcome = apply_event(state, ProtocolEvent::StartCycle).expect("dispatch #1");
        assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
        assert_eq!(
            outcome.state.last_stuck_math_audit_dispatched_cycle,
            Some(5)
        );
        let request = first_issued_request(&outcome.commands).clone();
        let mut response = initial_planner_response_for_test();
        response.request_id = request.id;
        response.cycle = request.cycle;
        let outcome = apply_event(
            outcome.state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("accept plan generation 1");
        let mut state = outcome.state;
        let plan_gen1 = state.audit_plan.clone().expect("generation-1 plan live");
        assert!(plan_gen1.initial_plan);
        // Reviewer works the plan: dismiss its task, then the run reaches
        // the next coverage-due StartCycle (target "u" still uncovered).
        {
            let plan = state.audit_plan.as_mut().unwrap();
            plan.tasks[0].dismissed = true;
            plan.tasks[0].dismissed_reason = "landed".into();
            plan.tasks[0].dismissed_at_cycle = Some(6);
        }
        let plan_gen1_dismissed = state.audit_plan.clone().unwrap();
        state.in_flight_request = None;
        state.stage = Stage::Start;
        state.cycle = 8; // post-StartCycle cycle 9; 9 - 5 = K ⇒ due again
        let outcome = apply_event(state, ProtocolEvent::StartCycle).expect("dispatch #2");
        assert_eq!(
            outcome.state.stage,
            Stage::StuckMathAudit,
            "the cadence pierces the live generation-1 plan at K"
        );
        assert_eq!(
            outcome.state.last_stuck_math_audit_dispatched_cycle,
            Some(9)
        );
        let request = first_issued_request(&outcome.commands).clone();
        let mut response = initial_planner_response_for_test();
        response.request_id = request.id;
        response.cycle = request.cycle;
        response.tasks[0].id = "plan-2".into();
        let outcome = apply_event(
            outcome.state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(response),
            },
        )
        .expect("accept plan generation 2");
        assert_eq!(
            outcome.state.superseded_audit_plan,
            Some(plan_gen1_dismissed),
            "generation 2 supersedes generation 1 with its dismissal trail intact"
        );
        let plan_gen2 = outcome
            .state
            .audit_plan
            .as_ref()
            .expect("generation-2 plan");
        assert!(plan_gen2.initial_plan);
        assert_eq!(plan_gen2.tasks[0].id, "plan-2");
        assert!(!plan_gen2.tasks[0].dismissed);
        assert!(outcome.state.stuck_math_audit.initial_planning.is_none());
    }

    #[test]
    fn coverage_planner_within_k_dispatches_worker() {
        // post-StartCycle cycle = 5; last = 3 ⇒ elapsed 2 < K ⇒ not due.
        // With the live planner plan suppressing everything else, the cycle
        // hands off to a Worker and no carrier is armed.
        let mut state = coverage_replanning_state_for_test(Some(3), 4);
        let mut plan = make_test_audit_plan();
        plan.initial_plan = true;
        state.audit_plan = Some(plan);
        state.activate_stuck_math_audit_latch("initial planner (test)".to_string());
        let outcome = apply_event(state, ProtocolEvent::StartCycle).unwrap();
        assert_eq!(outcome.state.stage, Stage::Worker);
        assert!(outcome.state.stuck_math_audit.initial_planning.is_none());
    }

    #[test]
    fn coverage_all_covered_dispatch_is_byte_identical_to_no_feature_state() {
        // Every configured target covered ⇒ the trigger is false forever and
        // the dispatch decision is byte-identical to a state without the
        // feature armed (the source field aside).
        let build = |armed: bool| {
            let mut state = base_state();
            state.stage = Stage::Start;
            state.cycle = 8;
            state.active_node = Some("a".into());
            state.last_stuck_math_audit_dispatched_cycle = Some(1);
            let mut plan = make_test_audit_plan();
            plan.initial_plan = true;
            state.audit_plan = Some(plan);
            state.activate_stuck_math_audit_latch("initial planner (test)".to_string());
            if armed {
                state.coverage_replanning_source =
                    Some(crate::model::InitialPlanningSource::PaperManuscript {
                        paper_tex_path: "paper/main.tex".into(),
                    });
            }
            state
        };
        let armed_outcome = apply_event(build(true), ProtocolEvent::StartCycle).unwrap();
        let plain_outcome = apply_event(build(false), ProtocolEvent::StartCycle).unwrap();
        assert_eq!(armed_outcome.state.stage, Stage::Worker);
        let mut armed_state = armed_outcome.state;
        assert_eq!(
            armed_state.coverage_replanning_source.take(),
            Some(crate::model::InitialPlanningSource::PaperManuscript {
                paper_tex_path: "paper/main.tex".into(),
            })
        );
        assert_eq!(armed_state, plain_outcome.state);
        assert_eq!(armed_outcome.commands, plain_outcome.commands);
    }

    /// The plan-review cadence's own state: every target covered (so the
    /// coverage arm is false forever) with a live planner-origin plan.
    /// This is the regime a real run reaches within a cycle or two of
    /// cycle 1, and where the plan used to stand unexamined for good.
    fn plan_review_state_for_test(last_dispatched: Option<u32>, cycle: u32) -> ProtocolState {
        let mut state = base_state();
        state.stage = Stage::Start;
        state.cycle = cycle;
        state.active_node = Some("a".into());
        state.last_stuck_math_audit_dispatched_cycle = last_dispatched;
        let mut plan = make_test_audit_plan();
        plan.initial_plan = true;
        plan.written_at_cycle = 1;
        // One live task and one dismissed, so the pinned reason's count is
        // exercised rather than trivially zero.
        plan.tasks = vec![
            crate::model::AuditTask {
                id: "open-task".into(),
                title: "still open".into(),
                ..Default::default()
            },
            crate::model::AuditTask {
                id: "done-task".into(),
                title: "already done".into(),
                dismissed: true,
                ..Default::default()
            },
        ];
        state.audit_plan = Some(plan);
        state.activate_stuck_math_audit_latch("initial planner (test)".to_string());
        state.plan_review_cadence_enabled = true;
        state.coverage_replanning_source =
            Some(crate::model::InitialPlanningSource::PaperManuscript {
                paper_tex_path: "paper/main.tex".into(),
            });
        state
    }

    #[test]
    fn plan_review_cadence_fires_over_a_live_plan_with_every_target_covered() {
        // The whole point: no target is uncovered, so the coverage arm is
        // dead, and without this cadence the planner would never run again.
        // post-StartCycle cycle = 11; last = 1 ⇒ elapsed 10 == K ⇒ due.
        let state = plan_review_state_for_test(Some(1), 10);
        assert!(!state.stuck_math_audit_coverage_replanning_trigger());
        let outcome = apply_event(state, ProtocolEvent::StartCycle).unwrap();
        assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
        let carrier = outcome
            .state
            .stuck_math_audit
            .initial_planning
            .as_ref()
            .expect("plan review arms the planner carrier");
        // Reuses the planner lane, so the burst gets the amend contract.
        assert!(carrier.coverage_replanning);
        assert!(carrier.uncovered_target_ids.is_empty());
        assert_eq!(
            outcome.state.stuck_math_audit.trigger,
            "plan review: the live plan was written at cycle 1 and has 1 task(s) still open — assess it against the Tablet as it stands and write the plan that fits"
        );
    }

    #[test]
    fn plan_review_within_k_dispatches_worker() {
        // Self-cadenced: K-1 cycles after the last dispatch the plan-review
        // arm is not yet due and the ordinary worker slot is untouched.
        // post-StartCycle cycle = 10; last = 1 ⇒ elapsed 9 < K ⇒ not due.
        let state = plan_review_state_for_test(Some(1), 9);
        let outcome = apply_event(state, ProtocolEvent::StartCycle).unwrap();
        assert_eq!(outcome.state.stage, Stage::Worker);
        assert!(outcome.state.stuck_math_audit.initial_planning.is_none());
    }

    #[test]
    fn plan_review_cadence_off_is_byte_identical_to_no_feature_state() {
        // The replay gate: an unseeded run must dispatch exactly as it did
        // before this feature existed, at a cycle where the cadence would
        // otherwise be long overdue.
        let build = |enabled: bool| {
            let mut state = plan_review_state_for_test(Some(1), 40);
            state.plan_review_cadence_enabled = enabled;
            state.coverage_replanning_source = None;
            state
        };
        let on = apply_event(build(true), ProtocolEvent::StartCycle).unwrap();
        let off = apply_event(build(false), ProtocolEvent::StartCycle).unwrap();
        assert_eq!(on.state.stage, Stage::StuckMathAudit);
        assert_eq!(off.state.stage, Stage::Worker);
        // And with the flag off, nothing about the dispatch differs from a
        // state that never carried the field.
        let mut plain = build(false);
        plain.plan_review_cadence_enabled = false;
        let plain_outcome = apply_event(plain, ProtocolEvent::StartCycle).unwrap();
        assert_eq!(off.state, plain_outcome.state);
        assert_eq!(off.commands, plain_outcome.commands);
    }

    #[test]
    fn plan_review_cadence_is_theorem_stating_exact() {
        // ProofFormalization gets no cadence — and needs none, because
        // `apply_advance_phase_approval` retires the plan at the boundary
        // (`advance_phase_retires_a_live_planner_plan`).
        let mut state = plan_review_state_for_test(Some(1), 40);
        state.phase = Phase::ProofFormalization;
        assert!(!state.stuck_math_audit_plan_review_trigger());
    }

    #[test]
    fn plan_review_cadence_does_not_revive_a_revision_plan() {
        // Revision plans keep full suppression: re-running the revision
        // planner on a byte-identical Tablet is the livelock the
        // suppression comment warns about.
        let mut state = plan_review_state_for_test(Some(1), 40);
        if let Some(plan) = state.audit_plan.as_mut() {
            plan.initial_plan = false;
            plan.revision_audit = true;
        }
        assert!(!state.stuck_math_audit_plan_review_trigger());
    }

    #[test]
    fn advance_phase_retires_a_live_planner_plan() {
        // The plan's subject is the theorem-stating DAG. Left standing it
        // followed the run into ProofFormalization and kept the stagnation
        // triggers suppressed there, where neither cadence reaches.
        let mut state = plan_review_state_for_test(Some(1), 40);
        state.gate_kind = GateKind::Advance;
        assert!(state.stuck_math_audit.active);
        apply_advance_phase_approval(&mut state);
        assert_eq!(state.phase, Phase::ProofFormalization);
        assert!(state.audit_plan.is_none());
        // Retired, not dropped: the plan and its dismissal trail stay readable.
        assert!(state
            .superseded_audit_plan
            .as_ref()
            .is_some_and(|plan| plan.initial_plan));
        // The latch was pinned by the plan's liveness alone; it must not be
        // left held by nothing with a stale trigger string on it.
        assert!(!state.stuck_math_audit.active);
        assert!(state.stuck_math_audit.trigger.is_empty());
    }

    #[test]
    fn advance_phase_retirement_is_behind_the_replay_gate() {
        // Unseeded runs must cross the boundary exactly as they did before
        // this feature: retiring a plan here is a state change at a
        // transition, so an ungated version would diverge on replay of any
        // pre-feature log.
        let mut state = plan_review_state_for_test(Some(1), 40);
        state.plan_review_cadence_enabled = false;
        apply_advance_phase_approval(&mut state);
        assert!(state.audit_plan.is_some_and(|plan| plan.initial_plan));
        assert!(state.stuck_math_audit.active);
    }

    #[test]
    fn advance_phase_leaves_an_ordinary_audit_plan_alone() {
        // Only planner-origin plans are retired here; an ordinary
        // stagnation-audit plan carries no suppression and is not this
        // transition's business.
        let mut state = plan_review_state_for_test(Some(1), 40);
        if let Some(plan) = state.audit_plan.as_mut() {
            plan.initial_plan = false;
        }
        apply_advance_phase_approval(&mut state);
        assert!(state.audit_plan.is_some());
        assert!(state.stuck_math_audit.active);
    }

    #[test]
    fn coverage_planner_defers_to_pending_on_demand_audit_request() {
        // A pending on-demand request keeps absolute priority: the dispatch
        // runs the ordinary audit role with the requester's pinned trigger
        // and arming is skipped.
        let mut state = coverage_replanning_state_for_test(Some(1), 4);
        state.pending_audit_request = Some(crate::model::PendingAuditRequest {
            origin: crate::model::AuditRequestOrigin::Worker,
            reason_kind: crate::model::AuditRequestReasonKind::Approach,
            reason: "the decomposition is circling".into(),
            requested_at_cycle: 4,
            request_id: 9,
        });
        let outcome = apply_event(state, ProtocolEvent::StartCycle).unwrap();
        assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
        assert!(
            outcome.state.stuck_math_audit.initial_planning.is_none(),
            "on-demand dispatch must not arm the coverage carrier"
        );
        assert!(
            outcome
                .state
                .stuck_math_audit
                .trigger
                .starts_with("worker requested audit (approach):"),
            "the on-demand trigger string wins; got {}",
            outcome.state.stuck_math_audit.trigger
        );
        assert!(outcome.state.pending_audit_request.is_none());
    }

    #[test]
    fn coverage_planner_arming_skipped_while_audit_lane_in_flight() {
        // Each in-flight audit-lane carrier blocks arming (the audit-role
        // mutex): the dispatched burst runs the in-flight lane's role and
        // the coverage carrier is not synthesized over it.
        let lanes: Vec<(&str, fn(&mut ProtocolState))> = vec![
            ("need_input_audit", |s| {
                s.stuck_math_audit.need_input_audit =
                    Some(crate::model::NeedInputAuditContext::default());
            }),
            ("gap_research", |s| {
                s.stuck_math_audit.gap_research = Some(crate::model::GapResearchContext::default());
            }),
            ("gap_plan_critique", |s| {
                s.stuck_math_audit.gap_plan_critique =
                    Some(crate::model::GapPlanCritiqueContext::default());
            }),
        ];
        for (label, arm_lane) in lanes {
            let mut state = coverage_replanning_state_for_test(Some(1), 4);
            arm_lane(&mut state);
            state.activate_stuck_math_audit_latch("lane in flight (test)".to_string());
            let outcome = apply_event(state, ProtocolEvent::StartCycle)
                .unwrap_or_else(|err| panic!("StartCycle with {label} lane: {err:?}"));
            let carrier = outcome.state.stuck_math_audit.initial_planning.as_ref();
            assert!(
                carrier.is_none(),
                "{label}: the coverage carrier must not clobber an in-flight lane"
            );
        }
    }

    #[test]
    fn coverage_planner_defers_to_verifier_frontier() {
        // The preempt requires the would-be dispatch to be Worker; a
        // non-empty paper frontier (target "v", coverage {"b"}, no paper
        // status yet) dispatches the verifier first and leaves the cadence
        // clock untouched.
        let mut state = coverage_replanning_state_for_test(Some(1), 4);
        state.configured_targets.insert("v".into());
        state.target_claims.insert("b".into(), set(&["v"]));
        state
            .committed_target_claims
            .insert("b".into(), set(&["v"]));
        state.live.coverage.insert("v".into(), set(&["b"]));
        state.committed.coverage.insert("v".into(), set(&["b"]));
        state
            .live
            .paper_current_fingerprints
            .insert("v".into(), "b=vb".into());
        state
            .committed
            .paper_current_fingerprints
            .insert("v".into(), "b=vb".into());
        let outcome = apply_event(state, ProtocolEvent::StartCycle).unwrap();
        assert_eq!(
            outcome.state.stage,
            Stage::VerifyPaper,
            "verifier work drains before the coverage planner"
        );
        assert!(outcome.state.stuck_math_audit.initial_planning.is_none());
        assert_eq!(
            outcome.state.last_stuck_math_audit_dispatched_cycle,
            Some(1),
            "a verifier dispatch must not consume the cadence"
        );
    }

