    #[test]
    fn coverage_trigger_conditions_each_block_individually() {
        let armed = |cycle: u32, last: Option<u32>| {
            let mut s = ProtocolState::default();
            s.cycle = cycle;
            s.configured_targets = set(&["t"]);
            s.live.coverage.insert("t".into(), BTreeSet::new());
            s.last_stuck_math_audit_dispatched_cycle = last;
            s.coverage_replanning_source =
                Some(crate::model::InitialPlanningSource::PaperManuscript {
                    paper_tex_path: "paper/main.tex".into(),
                });
            s
        };
        assert!(armed(5, Some(1)).stuck_math_audit_coverage_replanning_trigger());
        assert!(
            armed(5, None).stuck_math_audit_coverage_replanning_trigger(),
            "never-dispatched (None) is due"
        );
        // Feature not armed.
        let mut s = armed(5, Some(1));
        s.coverage_replanning_source = None;
        assert!(!s.stuck_math_audit_coverage_replanning_trigger());
        // Within K.
        assert!(!armed(5, Some(2)).stuck_math_audit_coverage_replanning_trigger());
        // All covered.
        let mut s = armed(5, Some(1));
        s.live.coverage.insert("t".into(), set(&["a"]));
        assert!(!s.stuck_math_audit_coverage_replanning_trigger());
        // Exact TheoremStating only.
        for phase in [
            Phase::ProofFormalization,
            Phase::RevisionStating,
            Phase::Cleanup,
        ] {
            let mut s = armed(5, Some(1));
            s.phase = phase;
            assert!(
                !s.stuck_math_audit_coverage_replanning_trigger(),
                "{phase:?} must not fire the coverage trigger"
            );
        }
    }

    // ===== GapResearch planner ↔ critic loop =====

    /// Drive: reviewer NeedInput -> auditor confirm -> GapResearch Planner
    /// dispatched. Returns the post-dispatch state + the planner request.
    fn route_to_gap_planner_for_test() -> (ProtocolState, WrapperRequest) {
        let (state, audit_request) = route_need_input_review_for_test();
        let confirm = StuckMathAuditResponse {
            request_id: audit_request.id,
            cycle: audit_request.cycle,
            status: ResponseStatus::Ok,
            confirm_need_input: true,
            report: "## Claim being audited\n".to_string()
                + &"the bounded tail of the recurrence is genuinely unjustified. ".repeat(8),
            ..StuckMathAuditResponse::default()
        };
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(confirm),
            },
        )
        .expect("confirm should dispatch the GapResearch Planner");
        let planner_request = first_issued_request(&outcome.commands).clone();
        (outcome.state, planner_request)
    }

    const ROUTE_TEX: &str =
        "Reduce the x∈{3,4,5} tail through the paper's Step4/Step5 elimination tree; \
         measure = elimination-tree depth, which descends where the multiplicity \
         recurrence did not. Add a bounded-cleanup support node discharging the gap.";

    fn planner_response(req: &WrapperRequest, route_tex: &str) -> StuckMathAuditResponse {
        StuckMathAuditResponse {
            request_id: req.id,
            cycle: req.cycle,
            status: ResponseStatus::Ok,
            report: "x".repeat(AUDIT_REPORT_TEXT_MIN_CHARS),
            route_tex: route_tex.into(),
            ..StuckMathAuditResponse::default()
        }
    }

    fn critic_verdict_response(
        req: &WrapperRequest,
        decision: &str,
        feedback: &str,
    ) -> StuckMathAuditResponse {
        let accept = decision.eq_ignore_ascii_case("accept");
        StuckMathAuditResponse {
            request_id: req.id,
            cycle: req.cycle,
            status: ResponseStatus::Ok,
            report: "x".repeat(AUDIT_REPORT_TEXT_MIN_CHARS),
            tasks: if accept {
                vec![AuditTask {
                    id: "gap-impl".into(),
                    title: "Author the bounded-cleanup support node".into(),
                    body: "Implement the accepted route: add the node, cite Step4/Step5, \
                           arrive mechanically closed."
                        .into(),
                    ..AuditTask::default()
                }]
            } else {
                Vec::new()
            },
            gap_decision: decision.into(),
            gap_feedback: feedback.into(),
            ..StuckMathAuditResponse::default()
        }
    }

    #[test]
    fn gap_planner_in_paper_candidate_dispatches_critic_with_isolated_payload() {
        let (state, planner_req) = route_to_gap_planner_for_test();
        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(planner_response(
                    &planner_req,
                    ROUTE_TEX,
                )),
            },
        )
        .expect("planner route should dispatch the critic");
        assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
        assert!(outcome.state.stuck_math_audit.gap_plan_critique.is_some());
        assert!(outcome.state.stuck_math_audit.gap_research.is_none());
        let critic_req = first_issued_request(&outcome.commands).clone();
        assert_eq!(critic_req.kind, RequestKind::StuckMathAudit);
        assert!(critic_req.fresh_context, "critic burst must be fresh");

        // Context isolation: the critic contract payload carries only the
        // route + gap brief, never the planner's report / scratch /
        // accumulated reasoning.
        let mut req = critic_req.clone();
        crate::request_contracts::populate_request_prompt_contracts(&mut req, None);
        let payload = crate::request_contracts::stuck_math_audit_contract_payload(&req);
        let text = serde_json::to_string(&payload).unwrap();
        assert!(text.contains("route_tex"), "critic gets the route");
        assert!(text.contains("gap_brief"), "critic gets the brief");
        assert!(
            !text.contains("accumulated_critic_feedback"),
            "critic must NOT receive the planner's accumulated feedback / reasoning"
        );
        // The planner's report text never appears in the critic payload.
        assert!(
            !text.contains(&"x".repeat(AUDIT_REPORT_TEXT_MIN_CHARS)),
            "critic payload must not echo the planner's report"
        );
        assert_eq!(payload["burst_role"], serde_json::json!("gap_plan_critic"));
        outcome.state.validate().expect("validate ok");
    }

    #[test]
    fn gap_critic_accept_routes_audit_plan_to_reviewer_rail() {
        let (mut state, planner_req) = route_to_gap_planner_for_test();
        // Snapshot the deviation registers: a critic ACCEPT only authorizes
        // the route into an AuditPlan; the actual deviation (if any) is
        // authored LATER by the worker via deviation_requests, never by the
        // gap path. So neither register may move on ACCEPT.
        let deviation_files_before = state.deviation_files.clone();
        let node_deviation_claims_before = state.node_deviation_claims.clone();
        // Reference-paper claims ride the same invariant: a critic ACCEPT
        // (a non-worker acceptance) must leave node_reference_grounds
        // untouched — only accepted WORKER responses move claims.
        if let Some(node) = state.live.present_nodes.iter().next().cloned() {
            state.configured_reference_papers.insert(
                crate::model::RefPaperId::from("refA"),
                crate::model::ReferencePaperSpec {
                    tex_path: "paper/refs/refA.tex".to_string(),
                    source_id: "Ref A".to_string(),
                },
            );
            state.node_reference_grounds.insert(
                node,
                BTreeSet::from([crate::model::RefPaperId::from("refA")]),
            );
        }
        let node_reference_grounds_before = state.node_reference_grounds.clone();
        let after_plan = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(planner_response(
                    &planner_req,
                    ROUTE_TEX,
                )),
            },
        )
        .expect("plan");
        let critic_req = first_issued_request(&after_plan.commands).clone();
        let outcome = apply_event(
            after_plan.state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(critic_verdict_response(
                    &critic_req,
                    "accept",
                    "",
                )),
            },
        )
        .expect("accept");
        // ACCEPT writes the critic's own AuditPlan (report + tasks,
        // need_input_audit) carrying the route, and routes to Reviewer via
        // the existing recovery rail.
        assert_eq!(outcome.state.stage, Stage::Reviewer);
        let plan = outcome
            .state
            .audit_plan
            .as_ref()
            .expect("ACCEPT must write an audit plan");
        assert!(plan.need_input_audit);
        assert!(!plan.tasks.is_empty());
        assert_eq!(
            plan.route_tex, ROUTE_TEX,
            "the accepted route rides inside the AuditPlan for the worker"
        );
        assert!(outcome.state.stuck_math_audit.gap_research.is_none());
        assert!(outcome.state.stuck_math_audit.gap_plan_critique.is_none());
        assert_eq!(
            first_issued_request(&outcome.commands).kind,
            RequestKind::Review
        );
        // FIX 4: a critic ACCEPT must NOT register any deviation; deviations
        // are authored later by the worker, not by the gap path.
        assert_eq!(
            outcome.state.deviation_files, deviation_files_before,
            "critic ACCEPT must not touch deviation_files"
        );
        assert_eq!(
            outcome.state.node_deviation_claims, node_deviation_claims_before,
            "critic ACCEPT must not touch node_deviation_claims"
        );
        assert!(
            !node_reference_grounds_before.is_empty(),
            "fixture must seed a reference-paper claim for the invariant to bite"
        );
        assert_eq!(
            outcome.state.node_reference_grounds, node_reference_grounds_before,
            "critic ACCEPT must not touch node_reference_grounds"
        );
    }

    #[test]
    fn gap_critic_reject_increments_counter_and_redispatches_planner() {
        let (state, planner_req) = route_to_gap_planner_for_test();
        let after_plan = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(planner_response(
                    &planner_req,
                    ROUTE_TEX,
                )),
            },
        )
        .expect("plan");
        let critic_req = first_issued_request(&after_plan.commands).clone();
        let outcome = apply_event(
            after_plan.state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::StuckMathAudit(critic_verdict_response(
                    &critic_req,
                    "reject",
                    "Step4 does not descend on this tail; try a depth measure",
                )),
            },
        )
        .expect("reject");
        // REJECT increments the counter, persists feedback, re-dispatches
        // the Planner with the feedback available.
        assert_eq!(outcome.state.gap_plan_reject_count, 1);
        assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
        assert!(outcome.state.stuck_math_audit.gap_research.is_some());
        assert_eq!(
            outcome.state.latest_global_repair_audit_decline_reason,
            "Step4 does not descend on this tail; try a depth measure"
        );
        let research = outcome
            .state
            .stuck_math_audit
            .gap_research
            .as_ref()
            .unwrap();
        assert_eq!(research.accumulated_critic_feedback.len(), 1);
        assert_eq!(
            research.accumulated_critic_feedback[0].critic_feedback,
            "Step4 does not descend on this tail; try a depth measure"
        );
        assert_eq!(
            research.accumulated_critic_feedback[0].route_tex, ROUTE_TEX,
            "the rejected route is recorded in the attempt history"
        );
        let planner_req2 = first_issued_request(&outcome.commands).clone();
        assert_eq!(planner_req2.kind, RequestKind::StuckMathAudit);
        assert!(planner_req2.fresh_context);
    }

    /// GATE: the math-mode GapResearch planner ↔ plan-critic loop is
    /// untouched by the PV give-up adjudication review. Same dispatch, same
    /// counter, same re-plan, same HumanGate at the same bound, same math
    /// role fragments — and the adjudication machinery never arms on a math
    /// run.
    #[test]
    fn math_mode_gap_plan_critic_loop_is_unchanged() {
        let n = crate::model::gap_plan_reject_limit();
        let (state0, planner_req0) = route_to_gap_planner_for_test();
        assert!(!state0.trust_base.required(), "this is a math-mode run");
        let mut state = Some(state0);
        let mut planner_req = planner_req0;
        let mut final_outcome = None;
        for i in 0..n {
            let after_plan = apply_event(
                state.take().expect("state present each iteration"),
                ProtocolEvent::WrapperResponse {
                    response: WrapperResponse::StuckMathAudit(planner_response(
                        &planner_req,
                        ROUTE_TEX,
                    )),
                },
            )
            .expect("the planner route dispatches the critic");
            // The planner→critic dispatch is unchanged: the math critic lane
            // is set and it selects the MATH role/output fragments.
            assert!(after_plan
                .state
                .stuck_math_audit
                .gap_plan_critique
                .is_some());
            let critic_req = first_issued_request(&after_plan.commands).clone();
            let mut req = critic_req.clone();
            crate::request_contracts::populate_request_prompt_contracts(&mut req, None);
            let payload = crate::request_contracts::stuck_math_audit_contract_payload(&req);
            assert_eq!(payload["burst_role"], serde_json::json!("gap_plan_critic"));
            let fragments = payload["prompt_fragments"]
                .as_array()
                .expect("fragment list")
                .iter()
                .map(|f| f.as_str().unwrap().to_string())
                .collect::<Vec<_>>();
            assert!(fragments
                .contains(&"stuck_math_audit/common/01_gap_plan_critic_role.md".to_string()));
            assert!(fragments.contains(
                &"stuck_math_audit/common/05_gap_plan_critic_output_contract.md".to_string()
            ));
            assert!(
                !fragments.iter().any(|f| f.contains("adjudication_critic")),
                "no PV adjudication fragment may reach a math burst: {fragments:?}"
            );

            let outcome = apply_event(
                after_plan.state,
                ProtocolEvent::WrapperResponse {
                    response: WrapperResponse::StuckMathAudit(critic_verdict_response(
                        &critic_req,
                        "reject",
                        &format!("reject #{i}"),
                    )),
                },
            )
            .expect("the critic reject applies");
            assert_eq!(
                outcome.state.gap_plan_reject_count,
                i + 1,
                "the math reject counter is the one that moves"
            );
            if i + 1 < n {
                assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
                assert!(
                    outcome.state.stuck_math_audit.gap_research.is_some(),
                    "a reject under budget re-dispatches the planner"
                );
                planner_req = first_issued_request(&outcome.commands).clone();
                state = Some(outcome.state);
            } else {
                final_outcome = Some(outcome);
            }
        }
        // Math-mode exhaustion still escalates to the real HumanGate — the
        // "record it and continue" resolution is PV-only.
        let final_outcome = final_outcome.expect("loop ran");
        assert_eq!(final_outcome.state.stage, Stage::HumanGate);
        assert_eq!(final_outcome.state.gate_kind, GateKind::NeedInput);
        let escalation = final_outcome
            .state
            .gap_human_escalation
            .as_ref()
            .expect("escalation payload snapshotted");
        assert_eq!(escalation.reason, "reject_convergence_failure");
        assert_eq!(escalation.rejected_plans.len() as u32, n);
        final_outcome.state.validate().expect("validate ok");
    }

    #[test]
    fn gap_loop_escalates_to_human_after_n_rejects() {
        // N = gap_plan_reject_limit() (default 2). The loop cannot livelock:
        // N consecutive rejects land on a real freshness-guarded HumanGate
        // carrying the full attempt record.
        let n = crate::model::gap_plan_reject_limit();
        let (state0, planner_req0) = route_to_gap_planner_for_test();
        let mut state = Some(state0);
        let mut planner_req = planner_req0;
        let mut final_outcome = None;
        for i in 0..n {
            let after_plan = apply_event(
                state.take().expect("state present each iteration"),
                ProtocolEvent::WrapperResponse {
                    response: WrapperResponse::StuckMathAudit(planner_response(
                        &planner_req,
                        ROUTE_TEX,
                    )),
                },
            )
            .expect("plan");
            let critic_req = first_issued_request(&after_plan.commands).clone();
            let outcome = apply_event(
                after_plan.state,
                ProtocolEvent::WrapperResponse {
                    response: WrapperResponse::StuckMathAudit(critic_verdict_response(
                        &critic_req,
                        "reject",
                        &format!("reject #{i}"),
                    )),
                },
            )
            .expect("reject");
            if i + 1 < n {
                assert_eq!(outcome.state.stage, Stage::StuckMathAudit);
                planner_req = first_issued_request(&outcome.commands).clone();
                state = Some(outcome.state);
            } else {
                final_outcome = Some(outcome);
            }
        }
        let final_outcome = final_outcome.expect("loop ran");
        assert_eq!(final_outcome.state.stage, Stage::HumanGate);
        assert_eq!(final_outcome.state.gate_kind, GateKind::NeedInput);
        let escalation = final_outcome
            .state
            .gap_human_escalation
            .as_ref()
            .expect("escalation payload snapshotted");
        assert_eq!(escalation.reason, "reject_convergence_failure");
        assert_eq!(
            escalation.rejected_plans.len() as u32,
            n,
            "every rejected route + feedback is carried to the human"
        );
        assert_eq!(
            first_issued_request(&final_outcome.commands).kind,
            RequestKind::HumanGate
        );
        final_outcome.state.validate().expect("validate ok");
    }

