    /// Audit round 2, B2 / named test 5 — the CLAIM is what enables the
    /// finding. Identical to the test above except the live refutation carries
    /// no `challenge_claims` entry (the state the pre-fix
    /// `apply_decide_polarity_flip` left behind for
    /// `dec2flt_total__Refutation` / `parse_number_faithful__Refutation`).
    ///
    /// The close still succeeds and still installs a clean closure record — so
    /// nothing halts, nothing complains — but `pv_refutation_findings` stays
    /// EMPTY. The run report silently omits "contract decided false". This is
    /// the defect the B2 load migration exists to prevent, and pinning it here
    /// is what makes that migration's necessity executable rather than argued.
    #[test]
    fn flipped_refutation_records_refutation_finding_on_close() {
        let mut state = proof_burst_state(
            &["Correct__Refutation"],
            &["Correct__Refutation", "b"],
            &["Correct__Refutation"],
        );
        let primary = trellis_kernel::ChallengeTargetId::from("goal:correct");
        let refutation = trellis_kernel::refutation_target_id(&primary);
        let primary_spec = trellis_kernel::ChallengeTargetSpec {
            kind: trellis_kernel::ChallengeTargetKind::Theorem,
            name: "Correct".to_string(),
            lean: "theorem Correct : a = b := by".to_string(),
            resolution: trellis_kernel::ChallengeResolution::Decide,
            ..trellis_kernel::ChallengeTargetSpec::default()
        };
        let refutation_spec = trellis_kernel::ChallengeTargetSpec {
            kind: trellis_kernel::ChallengeTargetKind::Theorem,
            name: "Correct__Refutation".to_string(),
            lean: trellis_kernel::refutation_statement(&primary_spec).unwrap(),
            ..trellis_kernel::ChallengeTargetSpec::default()
        };
        state
            .configured_challenge_targets
            .insert(primary.clone(), primary_spec);
        state
            .configured_challenge_targets
            .insert(refutation.clone(), refutation_spec);
        // NO `challenge_claims` entry — the stranded shape.
        state.deps.entry("Correct__Refutation".into()).or_default();
        state
            .pv_live_polarity
            .insert(primary.clone(), trellis_kernel::ChallengePolarity::Disprove);
        state.normalize_all_structural_state();
        state.ensure_node_metadata();
        assert!(
            !state
                .challenge_claims
                .contains_key(&NodeId::from("Correct__Refutation")),
            "fixture precondition: the refutation is stranded (claim-less)"
        );

        let request = issue_request_for_test(&mut state, RequestKind::Worker);
        let mut new_live = state.live.clone();
        new_live.open_nodes.clear();
        let mut probe = LocalClosureProbeOutput::default();
        probe.status = "ok".to_string();
        probe.kernel_axioms.insert("propext".to_string());
        let local_closure_revalidation = Some(complete_same_burst_batch_for_test([
            complete_same_burst_record_for_test("Correct__Refutation", &probe),
        ]));
        let mut local_closure_results = BTreeMap::new();
        local_closure_results.insert(NodeId::from("Correct__Refutation"), probe);

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(WorkerResponse {
                    request_id: request.id,
                    cycle: 5,
                    status: ResponseStatus::Ok,
                    outcome: WorkerOutcome::Valid,
                    snapshot: new_live,
                    local_closure_results,
                    local_closure_revalidation,
                    ..WorkerResponse::default()
                }),
            },
        )
        .expect("valid delta should apply");

        let node = NodeId::from("Correct__Refutation");
        assert!(
            outcome.state.local_closure_records.contains_key(&node),
            "the close itself is unaffected by the missing claim"
        );
        assert!(
            outcome.state.pv_refutation_findings.is_empty(),
            "SILENT DEFECT: a claim-less refutation decides the contract false \
             but records no finding — got {:?}",
            outcome.state.pv_refutation_findings
        );
    }

    // ===================================================================
    // B2c-gate Slice 2 — engine install-eligibility for IsabelleHol
    // ===================================================================
    //
    // Mirrors `accept_time_record_install_rejects_record_with_unapproved_axiom`
    // but for an IsabelleHol-targeted state (`state.tablet_target =
    // IsabelleHol` ⇒ `effective_node_target` resolves IsabelleHol). The
    // install-eligibility predicate becomes the server-cert gate
    // (`oracles_used.is_empty() && extra_shyps.is_empty() && theorem_exists`),
    // and the mathlib axiom ceiling is DROPPED (definitional axioms install).

    /// An IsabelleHol probe carrying an oracle (`z3`) must NOT install a
    /// record — `probe_ok` is false, so the node lands in failures +
    /// unverified (the verbatim-status fall-through branch).
    #[test]
    fn isabelle_accept_time_install_rejects_probe_with_oracle() {
        let mut state = proof_burst_state(&["a"], &["a", "b"], &["a"]);
        state.tablet_target = crate::backend::BackendId::IsabelleHol;
        let request = issue_request_for_test(&mut state, RequestKind::Worker);

        let mut new_live = state.live.clone();
        new_live.open_nodes.clear();

        let mut probe = LocalClosureProbeOutput::default();
        probe.status = "ok".to_string();
        probe.theorem_exists = true;
        probe.oracles_used.insert("z3".to_string());

        let mut local_closure_results = BTreeMap::new();
        local_closure_results.insert(NodeId::from("a"), probe);

        let outcome = apply_event(
            state,
            ProtocolEvent::WrapperResponse {
                response: WrapperResponse::Worker(WorkerResponse {
                    request_id: request.id,
                    cycle: 5,
                    status: ResponseStatus::Ok,
                    outcome: WorkerOutcome::Valid,
                    snapshot: new_live,
                    local_closure_results,
                    ..WorkerResponse::default()
                }),
            },
        )
        .expect("valid delta should apply");

        assert!(
            !outcome
                .state
                .local_closure_records
                .contains_key(&NodeId::from("a")),
            "an Isabelle probe carrying an oracle must NOT install a record",
        );
        assert!(
            outcome
                .state
                .local_closure_unverified_nodes
                .contains(&NodeId::from("a")),
            "oracle-rejected Isabelle node must surface in the unverified set",
        );
    }

